programs.sol:
"""A sparse lexical/structural approximation.

The main positive cues are Chinese yes/no tests, technical compound endings,
programming statements, and comparison uses of 'against'. Smaller rules
cover code types, escapes, and chat/header formatting. Unrecognized tokens
are left at zero; in particular, broad first-token casing heuristics are
omitted. These rules do not explain every lexical response.
"""
import regex as re

READS = ()

# These are complete technical expressions, not token IDs. The response is
# assigned only to a final piece of a word split across tokens.
TECHNICAL_ENDINGS = (
    ('二进制', 1.55),
    ('加法', 2.70),
    ('除法', 3.80),
    ('以太', 1.35),
    ('语句', 1.15),
    ('阻塞', 1.25),
    ('读写', 1.45),
    ('读取', 1.00),
    ('抓取', 1.00),
    ('挂载', 1.20),
    ('嵌套', 0.80),
    ('正弦', 1.00),
    ('余弦', 1.85),
    ('异步', 1.05),
    ('减震', 1.10),
    ('校验', 0.65),
    ('似然', 0.80),
    ('无符号', 0.60),
)
CODE_CONTEXT = re.compile(
    r'python|java|[;{}#]|代码|函数|线程|程序|条件|操作|事件', re.I
)
CONTROL_WORDS = {'if', 'switch'}
OTHER_STATEMENTS = {'print', 'break', 'catch', 'try', 'sql', 'import', 'match'}
COMPARISONS = re.compile(
    r'\b(compar\w*|check\w*|validat\w*|test\w*|search|plotted|assessments)\b'
)
OPPOSITION = re.compile(r'\b(match|game|race|case|develop\w*|python)\b')



def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    raw_old = b'' if first else carry[1]
    old = raw_old.decode('utf-8', errors='replace')[-100:]
    raw = (raw_old + prefix.token_bytes[-1])[-400:]
    text = raw.decode('utf-8', errors='replace')[-100:]
    value = 0.0
    if first and s == 'assistant':
        value = 1.21
    if s in {'是否', '能否'}:
        value = 1.00
    elif not first:
        for word, amplitude in TECHNICAL_ENDINGS:
            if text.endswith(word) and not s.endswith(word):
                value = amplitude
                break
        if s == '写' and value == 0.0:
            value = 1.10 if CODE_CONTEXT.search(old) else 0.15
        if s.strip().lower() in {'statement', 'statements', 'ements'}:
            previous = re.findall(r'[A-Za-z]+', old)
            last = previous[-1].lower() if previous else ''
            if last in CONTROL_WORDS:
                value = 1.40
            elif last in OTHER_STATEMENTS or s == 'Statement':
                value = 0.50
        elif s == ' against':
            words = re.findall(r'[A-Za-z]+', old.lower())
            last = words[-1] if words else ''
            if last == 'checking':
                value = 1.40
            elif COMPARISONS.search(old.lower()[-65:]):
                value = 0.70
            elif OPPOSITION.search(' '.join(words[-2:])):
                value = 0.43
    if not first:
        word = s.strip()
        if word in {'null', 'nil', 'false', 'undefined', 'bool', 'boolean'}:
            value = -0.10
        elif word in {'None', 'NULL', 'False'}:
            value = -0.05
        elif word.lower() in {'string', 'strings'}:
            value = 0.08
        elif word in {'function', 'functions'}:
            value = 0.06
        elif s == '\\t':
            value = -0.06
        elif s == 'n' and old.endswith('\\'):
            value = 0.045
        elif s == '\u00a0':
            value = 0.055
        if text.endswith('if_statements') and s == 'ements':
            value = 0.45
    if s == '<|im_start|>':
        value = -0.33 if first else -0.07
    elif s == '<|im_end|>':
        value = -0.05
    elif s == '</think>':
        value = -0.08
    if not first and s == ':' and old == 'Title':
        value = -2.35
    return (doc, raw), float(value)

"""Approximate English comparative and superlative degree marking.

Use dictionary adjective stems and ordinary -er/-est spelling rules, rejecting
many noun/verb lookalikes. Familiar size/measurement and ordering comparisons
are weaker than other comparisons. Rarer forms and split-off endings are
stronger. Also preserve a small positive response to doubled middle dots.
Only the current word fragment is carried; it resets between documents.
"""
from functools import lru_cache
import re
import wordnet
from wordfreq import zipf_frequency

QUANTITY={'more','most','less','least','fewer','fewest'}
QUALITY={'better','best','worse','worst'}
DISTANCE={'further','farther','furthest','farthest'}
IRREGULAR=QUANTITY|QUALITY|DISTANCE
# Genuine comparisons with competing noun or verb senses.
AMBIGUOUS={'clean','close','long','light','sharp','full','strange',
           'fit','fresh','dear','flat','low','cool','smooth','warm','dry','fast'}

def inflected(base, ending):
    if base.endswith('e'):
        return base[:-1] + ending
    if base.endswith('y') and base[-2] not in 'aeiou':
        return base[:-1] + 'i' + ending
    if re.fullmatch(r'[^aeiouy]+[aeiou][bdgmnprt]', base):
        return base + base[-1] + ending
    return base + ending

@lru_cache(None)
def stems(w):
    # The usual gaming noun, not comparative 'game' (brave).
    if w == 'gamer':
        return ()
    if len(w)<4 or not w.isascii() or not w.isalpha():
        return ()
    if not w.endswith(('er','est')):
        return ()
    ending = 'er' if w.endswith('er') else 'est'
    non_degree = {'out','aft','own','both','all','ain','fab'}
    bs = [b for b in wordnet.base_forms(w, 'adjective')
          if b != w and len(b) >= 3 and b not in non_degree
          and inflected(b, ending) == w]
    if not bs or zipf_frequency(w,'en') < 2.0:
        return ()
    ambiguous = bool(set(bs) & AMBIGUOUS)
    if w in wordnet.base_forms(w,'verb') and not ambiguous:
        return ()
    person = wordnet.is_a(w, 'person') and not ambiguous
    if person or wordnet.is_a(w, 'holiday'):
        return ()
    noun_types = {'noun.body','noun.quantity','noun.artifact','noun.plant'}
    if wordnet.categories(w) & noun_types and not ambiguous:
        return ()
    f=zipf_frequency(w,'en')
    return tuple(b for b in bs if zipf_frequency(b,'en')>=f-0.4)

@lru_cache(None)
def degree(w):
    return w in IRREGULAR or bool(stems(w))

READS = ()
MEASUREMENT = {'big','small','large','high','low','long','short',
               'old','young','new','great'}
ORDERING = {'early','late','near','less','few'}

@lru_cache(None)
def word_value(token):
    word = token.strip().lower()
    if word in QUALITY:
        return {'better': -1.31, 'best': -0.37,
                'worse': -1.89, 'worst': -1.29}[word]
    if word in DISTANCE:
        return -0.36
    bases = set(stems(word))
    if not bases:
        return {'ier': -0.65, 'iest': -1.36}.get(word, 0.0)
    frequency = min(5.8, max(3.0, zipf_frequency(word, 'en'))) - 4.5
    if word.endswith('er'):
        value = -3.02 + 0.68 * frequency
    else:
        value = -2.68 + 0.55 * frequency
    if bases & MEASUREMENT:
        value += 1.66 - 0.09 * frequency
    if bases & ORDERING:
        value += 2.1
    if any(re.fullmatch(r'[^aeiouy]+[aeiou][bdgmnprt]', b) for b in bases):
        value -= 1.15
    if token.strip()[:1].isupper():
        value += 0.42
    if not token[:1].isspace():
        value += 0.12
    return min(0.0, max(-9.0, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    starts_word = token[:1].isspace()
    full = word if starts_word else tail + word
    value = word_value(token)
    if tail and not starts_word and degree(full) and not degree(word):
        frequency = min(5.8, max(3.0, zipf_frequency(full, 'en'))) - 4.5
        if word.endswith('er'):
            value -= 3.27
        elif word.endswith('est'):
            value -= 2.85
        elif word == 'st':
            value -= 3.33
        value += 1.47 * frequency
    if token == '··':
        value = 1.51
    match = re.search(r'[a-z]+$', full)
    tail = match.group(0)[-30:] if match else ''
    return (doc, tail), value

"""Approximate a code-name boundary signal with local syntax rules.

Header suffixes, import aliases, wildcard imports and import line endings get
positive values. Path/namespace separators and some short code-name starts get
negative values. Constants summarize training examples of these syntax events;
individual identifiers' very different strengths are deliberately not memorized.
Only the last 320 characters are carried, with a reset at document boundaries.
"""
import re

READS = ()

CLASS_MODIFIERS = {
    'Abstract', 'Base', 'Basic', 'Custom', 'Default', 'Fake', 'Mock',
    'Mutable', 'Simple', 'Styled', 'Async',
}
CODE_WORDS = re.compile(
    r'\b(?:class|struct|interface|namespace|import|const|let|var|'
    r'def|public|private|protected|void|int|bool|string|extends)\b'
)
IMPORT = re.compile(
    r'^\s*(?:\d+\s+)?(?:import\s|from\s|use\s|package\s|using\s+namespace\b)'
)


def activation(token, tail):
    """Apply the most specific local syntax rule first."""
    line = re.split(r'\n|\\n|<\|endoftext\|>', tail)[-1]
    s = token.strip()
    importing = bool(IMPORT.search(line) or re.search(r'\bimport\s*\([^)]*$', tail))
    if re.match(r'^\s*(?:\d+\s+)?from\s', line) and ' import ' not in line:
        importing = False
    if re.match(r'^\s*(?:\d+\s+)?use\s', line) and not re.search(r'\\|::', line):
        importing = False
    include = bool(re.search(r'#\s*include\s*[<"]', line))
    code = bool(include or importing or CODE_WORDS.search(tail[-160:]) or
                re.search(r'\b(?:new|return)\s*$|@(?:type|generated)\b', line) or
                re.search(r'[{};]|:=|=>|::|\.[a-zA-Z_]+\(', tail[-100:]))

    # Header completion and import syntax.
    if token == '.h':
        if include:
            return 8.749 if '<' in line else 5.141
        return 0.555
    if token == '.hpp':
        return 3.051
    if s == 'std' and re.search(r'using\s+namespace\s*$', line):
        return 6.356
    if importing and token == ' as':
        if '*' not in line and ' from ' not in line:
            return 2.878
        return 0.999
    if importing and '*' in token:
        return 5.289
    if importing and ('\n' in token or '\\n' in token):
        return 0.804 if ';' in token else 0.725
    if importing and ';' in token:
        return -0.135
    if re.search(r'#\s*include\s*$', line) and re.fullmatch(r'\s*"', token):
        return -1.455
    if include and '\n' in token:
        return 0.396

    # Paths are contiguous non-whitespace runs with slash-separated segments.
    run = re.split(r'''[\s"'`<>]''', tail)[-1]
    path = ('/' in run or run in {'src', 'tests', 'test', 'lib'}) and '://' not in run
    path = path or include
    if importing and re.fullmatch(r'/', token) and path:
        return -1.637
    if '/' in token and not token.strip('/_.\'" '):
        levels = token.count('../')
        if levels:
            if importing or include:
                return -2.5 if levels > 1 else -1.2
            return -2.306 if levels > 1 else -0.22
        if '_' in token:
            return -1.43
        if token == '/' and path:
            if include:
                return -5.449
            if re.search(r'(?:^|/)(?:src|tests?|lib)(?:/|$)', run):
                return -1.86
            return -0.345
    if path and re.fullmatch(r'/[A-Za-z]', token):
        return -0.773 if token[-1].isupper() else -0.428
    if token == '\\' and re.match(r'^\s*(?:use|namespace)\b', line):
        return -2.122

    if s == 'public' and re.search(r'\b(?:class|struct)\b.*:\s*$', line):
        return -4.006
    if s in {'const', 'final', 'typeof', 'abstract'} and code:
        return -0.399
    # Only clear code-name boundaries; ordinary single letters stay near zero.
    word = s.lstrip('.(<_')
    attached = s.startswith(('.', '(', '<'))
    boundary = (token[:1].isspace() or attached or
                bool(tail) and (tail[-1].isspace() or tail[-1] in '(<{*~'))
    if code and boundary:
        if s in {'_', '__', '(_', '._'}:
            return -0.715
        if word in CLASS_MODIFIERS:
            return -1.386
        short = word.isascii() and word.isalpha() and len(word) <= 2
        if short:
            type_start = bool(re.search(
                r'^\s*(?:\d+\s*)?$|(?:new|class|interface)\s*$|[^\d\s]:\s*$', line
            ))
            if word.startswith('I') and word.isupper() and (attached or type_start):
                return -1.381
            if attached:
                return -0.464 if word[0].isupper() else -0.204
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, tail)
    return (doc, (tail + token)[-320:]), float(value)

programs.haiku:
"""Candidate 4: where a source file's module, header or class names begin and end.

Signed activation, by the line the token sits on:
- C/C++ `#include`: the header's extension (.h, .hpp) is strongly positive; the closing
  quote or bracket is mildly positive; the opening quote and path slashes are negative.
- Python `import x as` : the ` as` before an alias is positive.
- Java `import`: the package words ` java`/` static` and the line-ending `;` are mildly positive;
  capitalised class names are slightly negative.
- File paths: a bare `/` inside a path is negative, more so for deeper paths and /workspace.
- Class declarations: the words ` public`, ` T` or ` I` opening a base-class or type name are negative.
Everything else is predicted as 0.
"""
import re

READS = ()

HEADER_EXT = (".h", ".hpp")
CLOSE_INCLUDE = ('"\n', '>\n', '"\n\n', '>\n\n')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line = carry[1] if carry is not None and carry[0] == doc else ""
    tok = prefix.token_strings[-1]
    ls = line.lstrip()
    value = 0.0
    if ls.startswith("#include"):
        if tok in HEADER_EXT:
            value = 5.3
        elif tok in CLOSE_INCLUDE:
            value = 0.5
        elif tok == ' "' or tok == "/":
            value = -1.5
    elif re.match(r"(import|from)\b", ls):
        if tok == " as":
            value = 3.7
        elif tok in (" java", " static"):
            value = 1.0
        elif tok in (";\n", ";\n\n"):
            value = 1.0
        elif re.fullmatch(r"\.?\s?[A-Z]\w*", tok):
            value = -0.3
    elif tok == "/" and re.search(r"\w/\w", line):
        value = -1.7 if "/workspace" in line else -0.45
    elif re.search(r"\b(class|interface)\b", line) and tok in (" public", " T", " I"):
        value = -2.4
    line = line + tok
    if "\n" in tok:
        line = tok.split("\n")[-1]
    return (doc, line), value

programs.sol:
"""A document-onset signal plus a shallow grammar/formatting detector.

At document onset, Latin text, digits, indentation and source-file openers
usually give a negative value. Inside text, HAVE auxiliaries and past
participles following nouns give positive values. Modal/negative contexts
suppress HAVE. Imports, printf codes and nested escapes have separate
positive responses. Words must begin at a word boundary, not within a name.
Onset estimates also apply to identical repeated initial tokens; Title:
headers, carriage returns and empty comment lines have explicit exceptions.
These are coarse rules, not a token-identity reconstruction.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
PRONOUNS = set('i you he she it we they who which that there'.split())
AUXILIARIES = set(('be been being is are was were have has had do does did '
                  'can could will would shall should may might must '
                  'not never to').split()) | {"'t", '’t', "'ve", '’ve'}
# Irregular past participles; regular ones are recognized by -ed and WordNet.
IRREGULAR = set(('been done gone seen known shown given taken written spoken '
                 'made found bought brought thought caught taught sought '
                 'kept left lost paid said sold told sent spent built set '
                 'read put cut run won held heard felt met led').split())
FOREIGN_HAVE = set(('habe hast hat haben habt hatte hatten hätte hätten '
                    'avoir avait avaient avons avez ont '
                    'avere abbiamo avete hanno ho hai ha '
                    'haber hemos habéis han había habían har havde hadde').split())
START_DECLARATIONS = {'#include': -12.3, 'import': -9.2,
                      'package': -5.5, 'using': -4.1, 'from': -6.7}

@lru_cache(maxsize=8192)
def noun(word):
    function_words = {'a', 'an', 'the', 'as', 'in', 'on', 'at', 'by',
                      'for', 'of', 'to', 'and', 'or', 'but', 'more'}
    return (len(word) > 2 and word not in function_words
            and 'noun' in wordnet.parts_of_speech(word))

@lru_cache(maxsize=8192)
def participle(word):
    return (word in IRREGULAR or word.endswith('ed')) and (
        'verb' in wordnet.parts_of_speech(word))

@lru_cache(maxsize=8192)
def onset(s):
    w = s.strip()
    if s in START_DECLARATIONS:
        return START_DECLARATIONS[s]
    if s.startswith('/*'):
        return -8.8
    if s == '//\n':
        return 16.4  # An empty source-comment line, not an opening slash pair.
    if s.startswith('//'):
        return -5.2
    if s == '\r':
        return 5.55
    if s.startswith('#!/'):
        return -7.0
    if w and set(w) == {'#'}:
        return -2.7
    latin = bool(re.fullmatch('[a-zA-Z]+', w))
    value = -1.0 - 0.35 * s.startswith(' ')
    value += 1.1 * any(ord(c) > 127 for c in w)
    if latin:
        value += 0.6 - 0.1 * zipf_frequency(w.lower(), 'en')
        value -= 0.5 * (len(w) == 1)
    value -= 0.8 * w.isupper() + 1.7 * w.isdigit()
    value -= 0.8 * (not w and len(s) > 1)
    value -= 2.1 * ('\t' in s) + 0.8 * ('\n' in s)
    return value


def inside(s, tail):
    raw = s.strip()
    boundary = not tail or not tail[-1].isalpha() or not s or not s[0].isalpha()
    w = raw.lower() if boundary else ''
    match = re.search(r"([a-z]+(?:['’][a-z]+)?)\s*$", tail.lower())
    prev = match[1] if match else ''
    if w in {"'ve", '’ve'}:
        return 1.0
    if w in {'have', 'has', 'had'}:
        if prev in AUXILIARIES or prev.endswith((
                "n't", 'n’t', "'ve", '’ve', "'s", '’s',
                "'d", '’d', "'ll", '’ll')):
            return -0.13
        if prev in PRONOUNS:
            return 0.43 if w == 'have' else 0.38
        if w != 'have':
            return 0.24
        return 0.37 if noun(prev) else 0.06
    if w in FOREIGN_HAVE and not raw.isupper():
        return 0.9
    if w == 'since':
        return 0.55 if not prev or not noun(prev) else 0.07
    if w == 'because':
        return 0.12
    if w == 'spoken' and prev in {'language', 'languages'}:
        return 1.4
    if participle(w):
        if w == 'been':
            return -0.09
        if prev in PRONOUNS:
            return 0.0
        if prev in AUXILIARIES:
            return 0.02
        return 0.22 if noun(prev) else 0.03
    if s == 'import':
        if ';' in tail:
            return 1.55
        return 0.55 if 'package ' in tail else 0.05
    # C/Go printf conversion letters, and quotes nested inside escapes.
    if len(s) == 1 and s in 'diuoxXfFeEgGcsqpvT':
        if re.search(r'%[-+ #0]*[0-9]*(?:\.[0-9]*)?$', tail):
            return 1.3
    if s == '\\"' and tail.endswith('\\\\'):
        return 1.3
    if s == '_modules' and tail.endswith('node'):
        return 0.85
    if s and set(s) == {'\x00'}:
        return 1.3
    if s.strip() and set(s.strip()) == {'\\'} and len(s.strip()) >= 2:
        math = re.search(
            r'\\(?:frac|sqrt|text|begin|end|left|right|math|over|lim|sum)', tail)
        return -1.7 if math else 1.3
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, s, True, '')
    _, pos, first, repeated, tail = carry
    repeated = repeated and s == first
    value = onset(s) if repeated else inside(s, tail)
    if pos == 1 and first.lower() == 'title' and s == ':':
        value = 10.1
    return (doc, pos + 1, first, repeated, (tail + s)[-160:]), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:67, a document-start feature.

What it does
------------
This channel is almost silent inside a document. Its large values come at the
first token of each document (or of each packed row, where a document begins).
There the model has no earlier text to attend to, so the value is set by which
token it is. This program predicts that value from the token's kind, and
predicts 0 at every other position.

At a document start, the prediction is a sum of readable token-kind weights:

* a baseline of -1.2 for an ordinary token;
* code and markup openers (#include, import, package, /*, #!/, <, {, \\, //, a
  tab, and words like from, print, using, int) get -2.5 more: these are the
  strongest negative values, down to about -9 for "#include" or "/*";
* digits (0, 2, 16, ...) get -1.5 more;
* determiners and prepositions (a, an, the, of, to, it, that, this) get -1.0 more;
* whitespace-only tokens get -0.5 more;
* conjunctions and clause openers (and, in, is, for, if, has, have, as, new,
  just) get +0.7 more;
* capitalised words such as "The" or "Question" get +0.5 more;
* tokens with non-ASCII characters (CJK, Cyrillic, Arabic, Thai, curly quotes)
  get +1.2 more;
* chat special tokens such as <|im_start|> are 0.

Inside a document the value is almost always 0. Two exceptions carry a small
positive value: an "import" statement (about +1.0), and the auxiliary "have"
(has, have, had, 've, about +0.25), which is what the token "have" does before a
past participle.

Why it is shaped this way: at document starts the value is almost fully a
function of the token (within-token variance is zero there), and the
variance is mostly between token kinds. Mid-document positions carry little
token-identity signal, so they are predicted as 0.
"""

import re

READS = ()

CODE_SIGNS = "#/<{\\`"
CODE_WORDS = {
    "import", "package", "include", "from", "print", "using", "int", "const",
    "export", "void", "class", "def", "return", "namespace", "public", "static",
}
DETERMINERS = {"a", "an", "the", "of", "to", "it", "that", "this"}
CLAUSE_WORDS = {"and", "in", "is", "for", "if", "has", "have", "as", "new", "just"}
AUX_HAVE = {"has", "have", "had", "'ve", "’ve"}


def document_start_value(token):
    """Predicted activation for a token that begins a document."""
    if token.startswith("<|"):
        return 0.0
    word = token.strip()
    lower = word.lower()
    value = -1.2
    if (word and word[0] in CODE_SIGNS) or token.startswith("\t") or lower in CODE_WORDS:
        value -= 2.5
    if re.fullmatch(r"[0-9]+", word):
        value -= 1.5
    if lower in DETERMINERS:
        value -= 1.0
    if word == "":
        value -= 0.5
    if lower in CLAUSE_WORDS:
        value += 0.7
    if re.fullmatch(r"[A-Z][a-z]+", word):
        value += 0.5
    if any(ord(ch) > 127 for ch in token):
        value += 1.2
    return value


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[-1]
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_document:
        return None, float(document_start_value(token))
    if token == "import":
        return None, 1.0
    if token.strip() in AUX_HAVE:
        return None, 0.25
    return None, 0.0

programs.sol:
"""A structural-boundary feature, strongest at code separators.

Use the current token's punctuation, the previous token's shape, and a
200-character syntax sketch. Object/call separators, closing quotation/code/
math marks, and single-space tokens after whitespace get positive values. Most words
get zero away from document starts. This is a surface heuristic,
not a full programming-language parser.
"""
import re

READS = ()


def boundary_value(s, prev, line, recent, initial):
    t = s.strip()
    alpha = bool(prev) and prev[-1].isalpha()
    digit = bool(prev) and prev[-1].isdigit()
    spaced = bool(prev) and prev[0].isspace()
    whitespace = bool(prev) and prev.isspace()
    close = bool(prev) and prev[-1] in ')]}'
    identifier = any(c in prev for c in '_.([{')
    indented = bool(re.match(r'^\s{2,}\S', line))
    object_body = recent.rfind('{') > recent.rfind('}')
    brackets = any(line.rfind(a) > line.rfind(b)
                   for a, b in [('(', ')'), ('[', ']'), ('{', '}')])
    call = bool(re.search(r'[\w.]\([^\n)]*$', line))
    multiline_call = bool(re.search(r'[\w.]\([^)]*$', recent))
    quoted = any(len(re.findall(r'(?<!\\)' + re.escape(q), line)) % 2
                 for q in ('"', "'", '`'))
    code = bool(re.search(
        r'\b(def|class|return|const|let|var|function|public|private|for|import)\b'
        r'|[=;{}]|\w\.\w', line))
    attribute_value = bool(re.search(r'[:=]\s*["\'][^"\']*$', line))

    if s == ' ':
        return .49 * whitespace + .08 * object_body
    if not t:
        return -.01 if '\n' in s else 0.
    if all(c == '·' for c in t):
        return -.1
    if t in ('in', 'as') and s.startswith(' '):
        return 0.
    if t in ('=>', '->'):
        return .09 + .18 * indented - .13 * alpha
    if t.startswith(('#', '//')):
        return -.07 - 1.08 * initial
    if t in ('\\', '\\n'):
        return -.02
    if t.startswith('.') and t[1:].isalpha():
        return -.01 - .37 * initial
    if t == ':':
        if '\n' in s:
            return -.02
        return (-.05 + .95 * object_body + .25 * indented
                + .17 * alpha - .14 * quoted)
    if t.endswith(':') and t[-2:-1] in ('"', "'"):
        if '\n' in s:
            return .08
        return 1.25 + .44 * object_body - .61 * spaced + .34 * brackets
    if t.endswith(',') and not any(c.isalnum() for c in t):
        if '\n' in s:
            return .07 + .32 * indented + .11 * multiline_call
        if t == ',':
            return (.01 + .47 * multiline_call + .28 * brackets
                    + .19 * indented + .17 * object_body)
        if t[-2] in ('"', "'"):
            return .49 - .34 * spaced + .27 * brackets + .18 * code
        return .12 + .41 * multiline_call + .37 * object_body + .41 * close
    if t.endswith(';') and len(t) > 1 and not any(c.isalnum() for c in t):
        return .02
    if t == ';':
        return .07 if '\n' in s else .02 + .31 * object_body + .12 * code
    if t in ('"', "'"):
        if s[0].isspace() or '\n' in s:
            return 0.
        if t == "'":
            return .13 + .15 * quoted - .2 * spaced - .19 * identifier
        return .1 + .3 * quoted - .22 * spaced + .2 * alpha
    if t in ('”', '»', '」', '』', '》', '】'):
        return .08 + .33 * alpha - .12 * spaced
    if t.endswith('`') and not any(c.isalnum() for c in t):
        if s[0].isspace() or '\n' in s or len(t) > 2:
            return 0.
        return -.01 + .48 * quoted + .49 * alpha + .32 * digit
    if t.endswith('$') and not any(c.isalnum() for c in t):
        if s[0].isspace() or t[0] in '([{':
            return 0.
        return .47 - .39 * ('\n' in prev) - .29 * indented + .17 * alpha
    if t == '</':
        return .38
    if t.endswith('>') and not any(c.isalnum() for c in t):
        return .19 + .33 * attribute_value - .15 * spaced
    if t in ('?', '？', '!', '！'):
        return .1
    if t in (']', '}', ')'):
        return .12 if t == ']' else -.04 - .06 * call
    if any(c.isalpha() for c in t):
        return -.26 * initial
    if t.isdigit():
        return -.61 * initial
    return -.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        line, recent, prev = '', '', ''
    else:
        _, line, recent, prev = carry
    s = prefix.token_strings[-1]
    value = boundary_value(s, prev, line, recent, initial)
    line = (line + s).split('\n')[-1][-200:]
    recent = (recent + s)[-200:]
    return (doc, line, recent, s), float(value)

programs.haiku:
"""Punctuation that labels or separates items inside an open bracket (code and data).

Layer 1's MLP unit 68 writes into the residual stream mainly at the punctuation of
structured text, and stays near zero on prose and numbers. The program keeps the
bracket nesting of the text so far (a stack of open "(", "[", "{") and predicts:

- Key/value colons. A closing quote then colon (`"name":`, `'type':`) or a bare colon
  inside braces (`{ type: 'SET_X' }`) is strong; a colon in parentheses is weak, and a
  colon outside any bracket (prose, timestamps, `file.py:12`) is near zero.
- Item commas. A comma inside brackets (argument lists, arrays, objects) is moderate;
  a comma after a quoted string in braces (`"a",`) is strong; a top-level comma is ~0.
- Line numbers. Leading whitespace before the number of a numbered listing
  (`   12\\tdef f():`, as `cat -n` prints) is moderate.
- Backticks, dollar signs and `=>` are moderate wherever they appear.

Every other token predicts 0.
"""

READS = ()
OPEN, CLOSE = "([{", ")]}"
KEY_CLOSE = ('":', "':", '\\":')


def _numbered_listing(tail):
    """True when some line of the recent text starts with a number and a tab (`  12\\t`)."""
    import re
    return re.search(r"(^|\n)[ \t]*\d+\t", tail) is not None


def step(carry, prefix, upstream):
    stack, doc, tail = carry if carry else ([], None, "")
    if prefix.document_ids[-1] != doc:  # a new document: reset brackets and text
        stack, doc, tail = [], prefix.document_ids[-1], ""
    token = prefix.token_strings[-1]
    top = stack[-1] if stack else ""
    value = 0.0
    if token in KEY_CLOSE:
        value = 2.0 if top == "{" else 1.1
    elif token == '",':
        value = 1.0 if top in ("(", "{") else 0.3
    elif token == ":":
        value = {"{": 1.4, "(": 0.25}.get(top, 0.07)
    elif token == ",":
        value = 0.5 if top else 0.02
    elif token in ("`", "$", " =>"):
        value = 0.7
    elif token.strip() == "" and "\n" not in token:
        if tail.split("\n")[-1].strip() == "" and _numbered_listing(tail[-400:]):
            value = 0.3
        elif top == "{":
            value = 0.4
    for ch in token:
        if ch in OPEN:
            stack.append(ch)
        elif ch in CLOSE and stack:
            stack.pop()
    tail = (tail + token)[-400:]
    return (stack, doc, tail), float(value)

programs.sol:
"""Local number and spelling triggers, with a quiet default.

The second digit in an opening ``12`` produces a large pulse. Smaller pulses
occur on 30/31 (especially calendar dates), and on short/kurz/kort
and rz/lz spellings.
Homogeneous opening runs of carriage returns or carets are special cases.
Small document-opening adjustments cover digit runs, whitespace, import
headers, the possessive 'my', and chat-start markers.
This is a surface-pattern approximation, not a claim of one unified meaning.
"""
import calendar
import re

READS = ()
MONTHS = {name.lower(): i for i, name in enumerate(calendar.month_name) if i}
MONTHS.update({name.lower(): i for i, name in enumerate(calendar.month_abbr) if i})
WIDTH = str.maketrans('０１２３４５６７８９', '0123456789')


def day_response(tail, day):
    """Completing thirty or thirty-one; distinguish dates and larger numbers."""
    month = None
    match = re.search(r'([A-Za-z]+)\.?\s+3$', tail)
    if match:
        month = MONTHS.get(match[1].lower())
    match = re.search(r'(\d{1,2})月3$', tail)
    if match and 1 <= int(match[1]) <= 12:
        month = int(match[1])
    if month:
        return 1.07
    if re.search(r'\d3$', tail):
        return 0.22 if day == 30 else 0.08
    if tail.endswith((':3', '：3', '時3', '时3')):
        return 0.72 if day == 30 else 0.33
    return 0.49 if day == 30 else 0.33


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, previous, tail = 0, '', ''
        first, uniform = token, True
    else:
        _, n, previous, tail, first, uniform = carry
        uniform = uniform and token == first
    text = token.translate(WIDTH)
    joined = tail + text
    value = 0.0

    if n == 1 and previous == '1' and token == '2':
        value = 8.30
    elif n == 2 and tail == '12' and token == '2':
        value = 3.14
    elif text == '\r' and uniform:
        value = 2.03
    elif text == '^^^^' and uniform:
        value = 2.64
    elif previous.translate(WIDTH) == '3' and text in ('0', '1'):
        value = day_response(tail, 30 + int(text))
    elif (re.search(r'(?i)kurz\w*$', joined)
          and (text.startswith('z') or text.strip().lower() == 'kurz')):
        value = 1.05 if text != 'z' else 1.65
    elif text == 'z' and joined.lower().endswith('sturz'):
        value = 1.60
    elif text == 'z' and previous.lower().endswith('ur'):
        value = 0.65
    elif text == 'z' and previous.lower().endswith(('ol', 'kr')):
        value = 0.50
    elif text.strip().lower() == 'kort':
        value = 0.95
    elif text in ('ort', 'orte', 'orth'):
        if previous.strip().lower() == 'esk':
            value = 1.45 if text == 'ort' else 0.95
        elif previous.lower().endswith(('sh', 'k', 'st')):
            value = 1.30 if text == 'orth' else 0.95
    elif text.strip().lower() == 'short':
        value = 0.16
    elif text.strip().lower() == 'shortly':
        value = 0.70
    elif text == 'ly' and previous.lower().endswith(('short', 'cur')):
        value = 0.65
    elif text in '0123456789' and len(text) == 1 and uniform:
        value = 0.16 if text == '3' else -0.30
    elif token == '<|im_start|>':
        value = 0.415 if n == 0 else 0.022
    elif n == 0:
        if text.isspace():
            value = -0.25
        elif text.strip().lower() == 'my':
            value = -1.10
        elif text in ('import', 'package'):
            value = 0.44
    return (doc, n + 1, token, joined[-40:], first, uniform), value

"""Predict an opening-token pulse, sustained during exact repetitions.

Estimate its size from whitespace, line endings, symbols, digits and a
few familiar word/code classes. Reset at each document boundary and
return zero once varied tokens appear, except for the observed opening
digit patterns 12 and 122. This approximates the large boundary responses,
not the smaller context-dependent activity in ordinary text.
"""
READS = ()
DIGITS = (1.44, 0.006, 0.346, 1.189, 0.478,
          0.414, 0.517, 0.272, 0.243, 0.047)
PRONOUNS_AND_POSSESSIVES = set(
    'i me my mine myself we us our ours ourselves you your yours yourself '
    'yourselves he him his himself she her hers herself it its itself '
    'they them their theirs themselves'.split()
)
BE_FORMS = set('am is are was were be been being'.split())


def opening(s):
    if s == '<|endoftext|>':
        return 6.18
    if s.startswith('<|'):
        return -0.07
    if len(s) == 1 and s in '0123456789':
        return DIGITS[int(s)]
    if s.isspace():
        if '\n' in s:
            n = s.count('\n')
            return (2.33 / n ** 0.3 - 0.46 * s.startswith(' ')
                    + 0.8 * ('\r' in s))
        if '\r' in s:
            return 8.6
        if '\xa0' in s:
            return 3.2 + 1.4 * s.startswith(' ')
        if '\t' in s:
            return 1.41 if s == '\t\t' else 2.05
        n = len(s)
        return {1: 0.19, 2: 2.22, 3: 3.89}.get(n, 2.8)
    if '\n' in s:
        body = s.rstrip('\r\n').strip()
        n = s.count('\n')
        if body == '//':
            return 8.37
        if n > 1:
            return 1.1
        if body in ('.', '!', '/'):
            return 3.4
        if body == '。':
            return 2.8
        if body.endswith(');'):
            return 1.2
        return 1.9 + 0.8 * ('\r' in s)
    body = s.strip()
    if '\\' in body:
        if '"' in body or body in ('\\n', '\\t'):
            return 3.8
        if set(body) == {'\\'}:
            return 2.1 + 0.6 * max(0, len(body) - 2)
        return 2.0
    if not any(c.isalnum() for c in body):
        if len(body) > 1 and len(set(body)) == 1:
            if body[0] in '·^':
                return 5.9
            return {'//': -1.0, '**': -0.5, '##': 0.92,
                    '###': -0.16}.get(body, 1.8)
        if s.startswith(' ') and body in set('=+-*%.&/'):
            return 2.4
        if body in ('{', '}', ';', '%'):
            return {'{': 2.06, '}': 1.0, ';': 1.53, '%': 2.72}[body]
        if body == '，':
            return -0.41
        if s == ' (':
            return -0.32
        return 0.35
    if body == '#include':
        return 1.99
    if s == body and body in ('def', 'class', 'function'):
        return 4.37 if body == 'def' else 1.65
    if body in ('import', 'using'):
        return -0.6
    word = body.lower()
    if word in PRONOUNS_AND_POSSESSIVES:
        return -0.25
    if word in BE_FORMS:
        return -0.35
    if word in ('not', 'no'):
        return -0.9 if word == 'not' else 0.8
    if word in ('the', 'and', 'or'):
        return 0.37
    if word in ('but', 'so'):
        return -0.5
    if word == 'for':
        return 0.65
    if word in ('at', 'on', 'with'):
        return -0.3 if body.islower() else 0.0
    if not body.isascii():
        return -0.15
    return 0.08 if s.startswith(' ') else 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, opening(prefix.token_strings[-1]), True, 0)
    else:
        doc, first, value, repeating, position = carry
        carry = (doc, first, value, repeating and token == first,
                 position + 1)
    doc, first, value, repeating, position = carry
    prediction = value if repeating else 0.0
    # A reproducible exception among opening digit pairs: 12, then 122.
    if first == b'1' and token == b'2':
        if position == 1:
            prediction = 2.34
        elif position == 2 and prefix.token_bytes[-2] == b'2':
            prediction = 1.17
    return carry, prediction

"""A detector for abbreviation stops, not general sentence punctuation.

Periods after initials, conventional shortenings, and short non-word-like
strings get positive values. Common titles such as Mr. are much weaker than
technical abbreviations. Dense runs of stops strengthen unfamiliar
abbreviations. Middle dots after Han characters also fire. There are
small negative corrections at document starts and on numbers/spaces just
after an abbreviation. Everything else is near zero.
"""
import re
import regex
from functools import lru_cache
from wordfreq import zipf_frequency
import pycountry

READS = ()

COMMON_TITLES = set('mr mrs ms dr'.split())
OTHER_TITLES = set('prof rev hon supt sen lt'.split())
MONTHS = set('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
COMMON_LABELS = set('fig figs no nos al etc vs st sr jr'.split())
REFERENCES = set('pp vol vols ed eds nr ch chap sec sect art ref refs '
                 'cf ibid ib op cit ca eq eqs tab pl pg ff pt para'.split())
ORGANIZATIONS = set('co corp inc ltd'.split())
TECHNICAL = set('assoc dept dep univ inst natl intl acad soc assn gov govt '
                'gen dist ct cir app supp rep pat tech proc ser ann '
                'fed cert crim civ doc col stat reg hist math chem phys '
                'biol bot zool philos sci var sp cat cap lib tom dir '
                'rec publ res comm adv pres ex exh arch'.split())
UNITS = set('lb lbs oz ft hr approx max'.split())
CYRILLIC_ABBREVIATIONS = set('ул вул руб млн млрд тыс тис ст им мин'.split())
STATE_NAMES = tuple(s.name.lower() for s in pycountry.subdivisions
                    if s.country_code == 'US')

@lru_cache(maxsize=16000)
def frequency(word):
    return max(zipf_frequency(word, lang) for lang in ('en', 'de', 'fr', 'es'))


@lru_cache(maxsize=2000)
def state_prefix(word):
    """Shortened US state names, e.g. Calif., Mass., Mich."""
    return 3 <= len(word) <= 5 and any(
        name.startswith(word) and name != word for name in STATE_NAMES)


def kind(text):
    match = re.search(r'([^\W\d_]+)$', text)
    if not match:
        return 'other'
    word = match[1]
    low = word.lower()
    before = text[:match.start()]
    if len(word) == 1:
        if before.endswith('.'):
            return 'dotted_initial'
        if not before.rsplit('\n', 1)[-1].strip():
            return 'list_letter'
        if word.isupper():
            return 'capital_initial'
        if low in {'p', 'f', 'n', 'v'}:
            return 'reference_letter'
        return 'lower_initial'
    if low in COMMON_TITLES:
        return 'common_title'
    if low in MONTHS:
        return 'month'
    if low in COMMON_LABELS:
        return 'common_label'
    if low in OTHER_TITLES or low in REFERENCES:
        return 'reference'
    if low in ORGANIZATIONS:
        return 'organization'
    if low in TECHNICAL or low in CYRILLIC_ABBREVIATIONS:
        return 'technical'
    if word[0].isupper() and state_prefix(low):
        return 'technical'
    if low in UNITS:
        return 'unit'
    if re.fullmatch('[IVXLCDMivxlcdm]{2,6}', word):
        return 'roman_numeral'
    if not word.isascii():
        return 'word'
    if len(word) <= 4 and frequency(low) < 4:
        return 'short_capital' if word[0].isupper() else 'short_lower'
    if len(word) <= 8 and not any(c in 'aeiouy' for c in low):
        return 'consonant_abbreviation'
    return 'word'

VALUES = {
    'other': 0.0, 'word': 0.02,
    'capital_initial': 0.87, 'lower_initial': 0.45,
    'dotted_initial': 0.57, 'list_letter': 0.38,
    'reference_letter': 0.69, 'month': 1.41, 'common_title': 0.14,
    'common_label': 0.69, 'reference': 1.2, 'organization': 0.8,
    'technical': 1.4, 'unit': 1.1, 'roman_numeral': 0.44,
    'short_capital': 0.65, 'short_lower': 0.4,
    'consonant_abbreviation': 0.55,
}


def strength(text):
    category = kind(text)
    value = VALUES[category]
    # A run of stops suggests citations or abbreviated catalogue entries.
    dense = text[-100:].count('.') >= 3
    attached = re.search(r'\.[^\W\d_]+$', text)
    if dense and not attached:
        if category == 'short_capital':
            value += 0.6
        elif category == 'short_lower':
            value += 0.4
        elif category in {'word', 'technical', 'reference', 'lower_initial',
                          'list_letter', 'consonant_abbreviation'}:
            value += 0.3
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    old, previous_stop = ('', 0.0) if reset else carry[1:]
    token = prefix.token_strings[-1]
    value = 0.0
    stop = 0.0
    if token == '.':
        stop = strength(old)
        value = stop
    elif token.startswith('.') and len(token) <= 4:
        if all(c in ',;:)]}\\-' for c in token[1:]):
            value = 0.55 * strength(old)
    elif token == '·' and regex.search(r'\p{Script=Han}$', old):
        value = 1.05
    elif previous_stop > 0.3:
        if token.strip().isdigit():
            value = -0.55 * previous_stop
        elif token.isspace():
            value = -0.14 * previous_stop
        elif token.strip() == '§':
            value = -0.88 * previous_stop
    if reset or old.endswith('<|endoftext|>'):
        value = -0.4 if token.strip().isdigit() else -0.19
    return (doc, (old + token)[-120:], stop), float(value)

"""Approximate document-opening and token-format effects.

The largest modeled responses are two source-code openings: the argument
parentheses of an anonymous function, and the label in a filename tag.
Other document starts get a coarse estimate from script, case, and syntax;
ordinary positions receive only small punctuation corrections. Much of the
component's token-specific variation is deliberately left unexplained.
"""
import calendar
import unicodedata
import regex

READS = ()
QUESTION_WORDS = {'what', 'where', 'when', 'why', 'how'}
ARTICLES = {'a', 'an', 'the'}
WEEKDAYS = frozenset(calendar.day_name)
HAN = regex.compile(r'\p{Script=Han}')
LATIN = regex.compile(r'\p{Script=Latin}')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    s = text.strip()
    if carry is None or carry[0] != doc:
        age, previous = 0, ''
    else:
        age, previous = carry[1] + 1, carry[2]
    state = (doc, age, text)

    if age == 1 and previous.strip() == '(function' and s == '()':
        return state, 2.7
    if age == 1 and previous == '<' and s == 'filename':
        return state, -1.5

    if age == 0:
        if s == '(function':
            value = 0.59
        elif text.startswith('<|'):
            value = -0.31
        elif s.isdecimal():
            value = 0.20
        elif text in WEEKDAYS:
            value = -1.25
        elif s.lower() in QUESTION_WORDS:
            value = -0.70
        elif len(s) > 3 and s.lower().endswith('ly'):
            value = -0.70
        elif s.lower() in ARTICLES:
            value = -0.55 if s.istitle() and not text.startswith(' ') else -0.08
        elif not s:
            value = 0.35 if '\n' in text or '\t' in text else 0.0
        elif s == ',':
            value = 0.23
        elif ')' in s:
            value = 0.36
        elif s.startswith('<'):
            value = -0.25
        elif HAN.search(s):
            value = -0.34 if len(s) > 1 else 0.0
        elif LATIN.search(s) and s.istitle() and len(s) > 1:
            if text.startswith(' '):
                value = 0.0
            else:
                value = -0.43 if len(s) >= 7 else -0.16
        elif LATIN.search(s) and s.isupper():
            value = -0.20 if len(s) == 1 else -0.04
        else:
            value = -0.10 if text.startswith(' ') and len(s) >= 7 else 0.05
    else:
        if text == "'":
            value = -0.07
        elif text in {"')", "']"}:
            value = -0.13
        elif text in {"'re", "'ve", "'ll"}:
            value = 0.045
        elif text in {"'s", "'t"}:
            value = -0.022
        elif any(unicodedata.category(c) == 'Sc' for c in s):
            value = -0.05 if text.startswith(' ') else -0.01
        elif s == '.' and '\n' not in text:
            value = -0.008
        elif ')' in s and '\n' in text:
            value = 0.035
        else:
            value = -0.001
    return state, value

"""A sparse predictor using local phrases and word-piece spelling.

It recognizes honorifics, and so/such/sure/sorry after linking verbs,
with a particularly strong response to 'I am' contractions. It also
models short r-syllables: d+ir/ur is negative, many m+r pieces positive.
A small decaying response continues inside an unfinished word. These are
approximate cues, not a full account of the component's smaller responses.
Literal cues also cover Mary, an initial 'Title:', and middle-dot leaders.
"""
import re

READS = ()
COPULA = {
    'am': 9.0, "'m": 9.5, '’m': 9.5,
    'is': 4.3, "'s": 4.6, '’s': 4.6, 'was': 5.0,
    'are': 3.4, 'were': 3.3, "'re": 5.8, '’re': 5.5,
    'be': 1.8, 'been': 3.0, 'being': 3.0, 'ist': 3.2, 'sind': 3.0,
}
LINKING = set('feel feels felt seem seems seemed sound sounds look looks '
              'become becomes became get gets getting got'.split())
TITLES = {'Mr': 1.43, 'Mrs': 2.68, 'Miss': .92, 'Sir': .98, 'sir': .98,
          'mr': 1.0}


def phrases(s, previous, position):
    w, p = s.strip(), previous.strip()
    pl = p.lower()
    if w in TITLES:
        return TITLES[w]
    if w == 'Mary':
        return 3.5
    if s == '.':
        return {'Mr': 1.8, 'Mrs': 5.1, 'Dr': .92, 'Ms': 1.1}.get(p, 0.0)
    if s == ':' and p == 'Title' and position == 1:
        return 6.5
    if w and set(w) == {'·'} and len(w) >= 2:
        return 1.24
    if not s.startswith(' ') or w not in ('so', 'such', 'sure', 'sorry', 'really'):
        return 0.0
    degree = COPULA.get(pl, 0.0)
    if pl in LINKING:
        degree = 2.8
    if pl in ('have', 'has', 'had'):
        degree = 1.6
    if w in ('so', 'such'):
        if pl == 'just' and w == 'so':
            return 3.5
        if pl == 'not' and w == 'so':
            return 1.2
        return degree if degree else (.15 if p.isalpha() else 0.0)
    if w == 'sure':
        return .1 if not degree else max(.2, 1.35 * degree - 4.0)
    if w == 'sorry':
        return 3.5 if pl == 'so' else max(.05, .9 * degree - 4.1)
    return max(-.1, .5 * degree - 1.9)


def spelling(s, previous):
    w, p = s.strip().lower(), previous.strip().lower()
    end = previous[-1:].lower()
    if w in ('dir', 'dirs', 'dur', 'dire'):
        v = {'dir': -1.8, 'dirs': -2.7, 'dur': -3.0, 'dire': -.7}[w]
        return v * (.55 if s.strip()[0].isupper() else 1.0)
    # Turkish close-vowel copular/causative suffixes.
    if w in ('dır', 'dür', 'tır', 'tür'):
        return -1.8 if s.startswith(' ') else (-5.8 if w[0] == 'd' else -2.9)
    if len(s) > 5 or s != s.strip():
        return 0.0
    low = s.lower()
    if not re.fullmatch(r'[aeiouyıü]?r[a-zıü]*', low):
        return 0.0
    if s in ('RS', 'RT'):
        if end == 'm':
            return 11.5 if s == 'RS' else 5.0
        return {'s': 6.0, 'l': 2.5}.get(end, 0.0)
    if end == 'd':
        if low in ('ir', 'ır'):
            return -6.2
        if low in ('ur', 'ür', 'yr'):
            return -4.2
        if low in ('ire', 'ure', 'ura', 'oro'):
            return -1.8
        if re.fullmatch(r'[iı]r[iı][mln]?', low):
            return -5.0
        return -.6 if low in ('r', 'ri', 'ry', 'ru') else 0.0
    if end == 'ı' and low in ('rd', 'rm', 'ran', 'r'):
        return -5.0
    if end in ('l', 'r', 't') and low in ('ir', 'ır', 'ur', 'ür'):
        return 3.3 if p == 'l' and previous.startswith(' ') else (-.6 if end == 't' else -1.2)
    if p in ('l', 'n') and low in ('ary', 'arry'):
        return 2.2
    if p == 'j' and low.startswith('ir'):
        return 5.6 if len(low) == 2 else 2.5
    if end == 'm':
        if low.startswith('r') and len(low) <= 2 and s.islower():
            return 2.2
        if low in ('ire', 'ired'):
            return 4.0
        if low == 'ary':
            return 4.5
        if low in ('ura', 'uro', 'uri', 'iro'):
            return 1.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0.0)
    _, previous, position, last_value = carry
    s = prefix.token_strings[-1]
    value = phrases(s, previous, position) + spelling(s, previous)
    if value == 0.0 and s[:1].isalpha() and previous[-1:].isalpha():
        value = .2 * last_value
    return (doc, s, position + 1, value), float(value)

"""Recognize degree and participial modifiers inside noun phrases.

Strong positive predictions mark degree and participial modifiers after
articles or possessives, not ordinary predicative uses like `is very`.
Separate rules cover time/place idioms, multilingual quantity words, and
source imports. Negative rules cover some anaphoric phrases, numbered
Chinese episodes, and a title-field colon. Other tokens are near zero,
with a small document-initial bias. Histories reset between documents.
"""
READS = ()
ARTICLES = {'a', 'an', 'the'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their', "'s", '’s'}
DETERMINERS = ARTICLES | POSSESSIVES | {'some', 'any'}
ORDINALS = {'first', 'second', 'third', 'fourth', 'fifth'}
INTENSIFIERS = {'really', 'extremely', 'highly', 'truly'}
DEGREE_MODIFIERS = {
    'especially', 'particularly', 'relatively', 'comparatively',
    'substantially', 'significantly', 'notably', 'unusually',
    'exceptionally', 'remarkably', 'incredibly', 'severely', 'rather',
}
# These participles get stronger predictions as noun modifiers than as verbs.
PARTICIPLES = {
    'continued': 4.5, 'added': 3.6, 'included': 2.4,
    'shared': 0.8, 'given': 0.6,
}
MORE_WORDS = {'más', 'mais', 'более', '更', '更为', '更加', '더'}
MOST_WORDS = {'наиболее', '最も', '가장'}
# Vietnamese: one/a, plural determiner, many, and additional/more.
VIETNAMESE_QUANTITY = {'một': 1.2, 'những': 0.9, 'nhiều': 0.8, 'thêm': 3.0}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = [] if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = [t.strip().lower() for t in history]
    prev = words[-1] if words else ''
    before = words[-2] if len(words) > 1 else ''
    noun_phrase = prev in DETERMINERS
    if prev in ORDINALS:
        noun_phrase |= before in DETERMINERS
    if prev == 'and':
        noun_phrase |= any(w in DETERMINERS | {'most'} for w in words[-3:-1])
    value = 0.0
    if not history:
        value = -0.3 if not word or word.isdigit() else -0.16
        if word.startswith('<|'):
            value = 0.1
    if word == ':' and history == ['Title']:
        value = -6.5
    elif word == 'most':
        value = 0.02
        if noun_phrase:
            value = 2.0 if prev in POSSESSIVES else 1.4
            if prev == 'the' and before == 'of':
                value = 2.3
    elif word == 'more':
        value = 0.24
        if noun_phrase:
            value = 1.18 if prev in {'a', 'an'} else 0.75
    elif word == 'many':
        value = 1.6 if noun_phrase else -0.02
    elif word == 'less':
        value = 0.62 if noun_phrase else 0.18
    elif word == 'very':
        value = 0.4 if noun_phrase else -0.06
        if prev in {'a', 'an', 'some'}:
            value = 1.42
    elif word == 'pretty':
        value = 0.65 if noun_phrase else -0.06
    elif word in INTENSIFIERS:
        value = 1.15 if noun_phrase else -0.06
    elif word in DEGREE_MODIFIERS:
        value = 0.6 if noun_phrase else -0.03
    elif word == 'increasingly':
        value = 2.6 if noun_phrase else 0.6
    elif word in PARTICIPLES:
        value = 0.65 if word == 'continued' else 0.0
        if noun_phrase:
            value = PARTICIPLES[word]
        elif word == 'continued' and prev in {'for', 'by', 'alongside'}:
            value = 3.8
    elif word == 'continuing':
        value = 0.85 if noun_phrase else -0.12
    elif word in VIETNAMESE_QUANTITY:
        value = VIETNAMESE_QUANTITY[word]
    elif word == '集' and prev and prev[-1].isnumeric():
        value = -2.0
    elif word in MORE_WORDS:
        value = 0.6
    elif word in MOST_WORDS:
        value = 1.3
    elif word == 'time':
        if prev == 'a':
            value = 0.5
            if before == 'at':
                value = 5.6
            elif before in {'for', 'upon', 'in', 'with', 'after'}:
                value = 1.3
        elif prev == 'one':
            value = 2.0
        elif prev in {'that', 'any'}:
            value = 0.4
    elif word == 'once':
        value = {'at': 1.05, 'for': 1.95, '#pragma': 1.4}.get(prev, -0.12)
    elif word == 'top':
        if prev == 'a':
            value = 0.75
        elif prev == 'the' and before in {'at', 'to', 'on', 'from'}:
            value = 1.15
    elif word == 'right':
        value = 0.2 if prev in DETERMINERS else 0.0
        if prev == 'a':
            value = 1.05
    elif word == 'means':
        value = {'a': 2.3, 'the': 0.9, 'by': 0.6, 'of': 0.6}.get(prev, 0.0)
    elif word == 'its' and prev == 'for':
        value = 0.68
    elif word == 'such':
        value = -0.5 if prev in {'in', 'of', 'all', 'no'} else -0.1
        if prev == 'any':
            value = -1.6
    elif word in {'these', 'those'}:
        value = -0.1
        if prev == 'follow':
            value = -1.7
        elif prev == 'of' and before in {'one', 'any'}:
            value = -1.0
    elif word == 'that':
        value = -0.05
    elif word == '#include':
        value = 3.5
        if not history:
            value = -0.66
        elif history[-1].rstrip().endswith('"'):
            value = 7.0
        elif history[-1].rstrip().endswith('>'):
            value = 4.2
    elif word == 'include' and prev in {'#', '{%'}:
        value = 2.7
    elif word == 'import' and (not history or history[-1].endswith('\n')):
        value = 0.3
        if history and history[-1].endswith('\n\n'):
            value = 0.95
    elif word == 'crate' and prev == 'extern':
        value = 1.3
    return (doc, (history + [token])[-4:]), value

programs.haiku:
"""Layer-1 MLP down-projection feature 74: a sparse detector for a few word patterns.

Most of the time it predicts 0. It fires when a degree or quantity word sits
right after an article ("the most", "a very", "a more", "the added", "your
continued"), on "time" in the idiom "at a time", and on "#include" as a C
preprocessor directive. It also fires on "more/most" words in other languages
(más, mais, thêm, 更, наиболее). It is slightly negative on "such" and "these",
and on the first token of each document. Values are typical activations.
"""

READS = ()

ARTICLES = {"a", "an", "the", "your", "their", "its"}

# activation when the word directly follows an article or determiner
AFTER_ARTICLE = {
    "most": 1.6, "very": 1.4, "more": 1.0, "added": 1.5,
    "continued": 4.5, "many": 1.0, "top": 0.4,
}

# activation of the same words elsewhere
ELSEWHERE = {"most": 0.25, "very": 0.1, "more": 0.22, "continued": 0.6}

# "more / most" words in other languages
OTHER_LANGUAGE = {
    "thêm": 3.3, "наиболее": 1.7, "最も": 1.3, "más": 0.7,
    "mais": 0.3, "更": 0.3, "более": 0.7,
}

NEGATIVE = {"such": -0.15, "these": -0.15}


def step(carry, prefix, upstream):
    words = [s.strip() for s in prefix.token_strings]
    cur = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    prev2 = words[-3] if len(words) > 2 else ""
    if len(words) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        value = -0.15  # first token of a document
    elif cur == "#include":
        value = 3.7
    elif cur == "include" and prev == "#":
        value = 2.5
    elif cur == "time" and prev == "a":
        value = 5.5 if prev2 in ("at", "At", "one") else 1.0
    elif prev in ARTICLES and cur in AFTER_ARTICLE:
        value = AFTER_ARTICLE[cur]
    elif cur in ELSEWHERE:
        value = ELSEWHERE[cur]
    elif cur in OTHER_LANGUAGE:
        value = OTHER_LANGUAGE[cur]
    else:
        value = NEGATIVE.get(cur, 0.0)
    return carry, float(value)

programs.sol:
"""A coarse, sparse line-ending response.

Two/three-space hard breaks are negative unless the line is empty;
earlier pairs of spaces soften this response. HTML break prefixes and
backslash/TeX row endings are negative too. Single breaks are weaker,
except after numeric metadata, timestamps, quote attributions, or math.
Multiple-newline tokens get a small baseline. Separate narrow rules cover
document-initial numeric/caret spikes. Fine lexical variation is omitted.
"""
import math
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 0, {}, True, True)
    _, pos, line, spaces, counts, twos, carets = carry
    s = prefix.token_strings[-1]
    value = 0.0
    count = counts.get(s, 0)
    body = (line + s.split('\n')[0]).rstrip()

    if s in ('  \n', '   \n', '  \r\n'):
        value = -1.8 / math.sqrt(1 + spaces) if body else 0.15
    elif s == '\\\n':
        value = -2.6 if '$' in body and '&' in body else -1.2
    elif s.lower() == '<br':
        value = -1.5 / math.sqrt(1 + count)
    elif s.count('\n') == 1:
        label, colon, rest = body.rpartition(':')
        field = (
            colon and 0 < len(label) < 50
            and any(c.isalpha() for c in label)
            and re.search(r'\d[\]\)]?$', rest)
            and not any(c in body for c in '=;{}_')
            and not body.startswith((' ', '\t', '•'))
        )
        if len(body) < 120 and re.search(
            r'\boriginally posted by\b', body, re.I
        ):
            value = -1.8
        elif len(body) < 120 and re.search(
            r'\d.*\b(?:AM|PM|GMT|UTC)$', body
        ):
            value = -2.0 if body.startswith('•') else -1.0
        elif field:
            value = -0.65 if spaces < 5 else -0.15
        elif body.rstrip('.').endswith('$'):

            value = -0.8
        elif body[-1:].isdigit() and not body.startswith((' ', '\t')):
            if body.startswith('•'):
                value = -2.0 if len(body.split()) <= 4 else -0.4
            elif body.startswith(('-', '*', '#')):
                value = -0.08
            else:
                value = -0.30 if spaces < 5 else -0.06
        else:
            value = -0.02 if body and not body.startswith((' ', '\t')) else 0.0
    elif s.count('\n') > 1:
        value = 0.012

    # Startup exceptions: a leading digit, an initial 12..., and caret rules.
    if pos == 0 and len(s) == 1 and s.isdecimal():
        value = -0.28
    if pos > 0 and twos and s == '2':
        value = -6.045 / (2.52 ** (pos - 1))
    if carets and s == '^^^^':
        value = -3.23

    # 'twos' means the document has contained only 1 followed by 2s.
    twos = s == '1' if pos == 0 else twos and s == '2'
    carets = carets and s == '^^^^'
    if '\n' in s or s.lower() == '<br':
        counts[s] = count + 1
    spaces += s.count('  ')
    line = (line + s).rsplit('\n', 1)[-1]
    return (doc, pos + 1, line, spaces, counts, twos, carets), float(value)

programs.haiku:
"""Line breaks in web pages and forum threads, plus a number opening a document.

Mostly quiet. Its clearest response is on the newline token that ends a line, and it depends
on what that line says:
- strongly negative (about -0.75) on forum or listing metadata: bullet items ("• 3") and
  fields such as "Posts: 10", "Joined", "Liked", "Views", "Pages", "Originally Posted by";
- negative (about -0.35) on a line with a date or clock time ("Sep 13, 2007", "09:10 AM");
- mildly negative (about -0.28) on a line that ends in a digit (a count, a year, a number);
- positive (about +0.5) on a bare section heading such as "References", "External links",
  "Introduction", "Advertisement" or "Discussion".
A document whose first token is a number is also slightly negative (about -0.25).
Every other token, and every line break after ordinary prose, is predicted as 0.
"""

import re

READS = ()

METADATA = re.compile(
    r"•|Posts|Joined|Liked|Likes|Views|Member|Posted|Pages|Replies|Last Post|started by|Originally"
)
DATE = re.compile(
    r"\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)[a-z]*\.?\s+\d"
    r"|\d{1,2}:\d{2}|\b(am|pm|AM|PM)\s*$"
)
HEADING = re.compile(
    r"(References|External links|Introduction|Advertisement|Discussion|Description|Definitions|Summary)\s*$"
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    line = "" if new_doc else carry
    if token != "\n":
        value = -0.25 if new_doc and token.strip().isdigit() else 0.0
        return line + token, value
    text = line.strip()
    if METADATA.search(text):
        value = -0.75
    elif DATE.search(text):
        value = -0.35
    elif text[-1:].isdigit():
        value = -0.28
    elif HEADING.search(text):
        value = 0.5
    else:
        value = 0.0
    return "", value

programs.sol:
"""Approximate a text-fragment continuation signal.

Count the token pieces in the current uninterrupted run of letters. Starting
with its third piece, give short pieces a positive value (larger for a short
non-ASCII letter). Common English grammatical endings also get a bonus
from the second piece onward. UTF-8 continuation bytes get a positive value.
Han tokens receive near-zero values rather than a word-fragment bonus.
New documents reset the count and have a negative first-token offset, scaled by token size
and whether its characters are ASCII. A colon after an initial "Title" label
has a separate large positive response. Other positions stay close to zero.
"""
import unicodedata

READS = ()

# Plural, tense/participle, comparison, and adverbial endings.
GRAMMATICAL_ENDINGS = frozenset({
    's', 'es', 'ed', 'ing', 'en', 'er', 'est', 'ly',
})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, pieces, position = (b'', 0, 0) if first else (
        carry[1], carry[2], carry[3] + 1
    )

    if s.isalpha():
        pieces += 1
    else:
        pieces = 1 if s[-1:].isalpha() else 0
    state = (doc, b, pieces, position)
    text = s.strip()

    if first:
        if not text.isascii():
            value = -1.08
        elif len(text) <= 1:
            value = -0.49 if text.isalpha() else -0.35
        else:
            value = -0.52 if s[:1].isspace() else -0.67
    elif position == 1 and previous == b'Title' and b == b':':
        value = 13.48
    elif b and 0x80 <= b[0] < 0xC0:
        # This token starts inside a character begun by the previous token.
        if previous.decode('utf-8', 'replace')[:1].isspace():
            value = 0.28
        elif previous and 0x80 <= previous[0] < 0xC0:
            value = 0.64
        else:
            value = 0.48
    elif pieces >= 2 and s in GRAMMATICAL_ENDINGS:
        value = 0.15 if pieces == 2 else 0.27
    elif pieces >= 3:
        if len(b) <= 2:
            value = 0.15 if text.isascii() else 0.36
        elif 'CJK' in unicodedata.name(text[0], ''):
            value = -0.013
        else:
            value = 0.08
    elif len(b) <= 3:
        value = 0.001
    else:
        value = -0.008 if text.isascii() else -0.046
    return state, value

"""A sparse approximation to local phrase-completion responses.

The strongest negatives mark reduced need/expectation clauses ("as needed",
"if necessary") and representation names in identifiers ("to_string").
Smaller rules cover pronoun complements, deictic/spatial phrases, "X by X",
weekdays after "on", and the listed conventional bare complements. Chinese
pronouns and horizontal directions have corresponding complement rules.
Document starts receive small positive character-class baselines; other
cases predict zero.
"""
import re

READS = ()
NECESSITY = {'needed', 'necessary', 'required'}
EXPECTATION = {'expected', 'desired', 'intended', 'requested'}
OBJECTS = {'me', 'you', 'him', 'her', 'it', 'us', 'them', 'whom'}
TEXT_FORMATS = {'s', 'str', 'string', 'bytes', 'byte', 'json', 'xml', 'yaml'}
CONTAINERS = {'dict', 'dictionary', 'list', 'array', 'vec', 'vector',
              'set', 'map', 'tuple'}
SCALAR_TYPES = {'int', 'integer', 'float', 'double', 'bool', 'boolean'}
ZH_PREPS = set('为為给給替向对對与與从從於于把被')
ZH_PRONOUNS = {'我', '你', '您', '他', '她', '它', '其', '之', '此',
               '我们', '我們', '你们', '你們', '他们', '他們'}
RESOURCES = {'file', 'url', 'stream', 'reader', 'writer', 'buffer'}


REFERENCE = {'above', 'below', 'described', 'specified', 'stated',
             'mentioned', 'noted', 'indicated', 'defined', 'explained'}
DEICTIC = {'here', 'there', 'above', 'below'}
WEEKDAYS = {'monday', 'tuesday', 'wednesday', 'thursday', 'friday',
            'saturday', 'sunday'}
# Selection keys and argument-passing modes.
SELECTION_OR_PASSING = {'name', 'type', 'index', 'path', 'reference',
                        'value', 'key'}
# Selected conventional article-free complements, pooled by preposition.
BARE_COMPLEMENTS = {
    'in': ({'advance', 'public', 'private', 'writing', 'code', 'need',
            'radians', 'english', 'chinese'}, -0.85),
    'on': ({'average', 'stage', 'demand', 'request'}, -1.3),
    'by': ({'definition', 'default', 'contradiction', 'hand', 'parts'}, -1.5),
    'for': ({'free', 'sure', 'now'}, -0.7),
    'at': ({'random', 'present', 'night', 'sea', 'school', 'church'}, -0.65),
}


def word(token):
    """Last word, recognizing snake_case and camelCase boundaries."""
    parts = re.findall(r'[A-Z]?[a-z]+|[A-Z]+(?![a-z])', token)
    return parts[-1].lower() if parts else token.strip().lower()


def response(prev, cur, prev2, raw):
    """Predict from the current word and the preceding two token words."""
    if prev in {'as', 'if', 'when', 'whenever', 'where'}:
        if cur in NECESSITY:
            if cur == 'needed' and prev in {'as', 'when'}:
                return -4.2
            return -2.0 if cur == 'required' and prev != 'as' else -3.2
        if cur in EXPECTATION:
            return -3.4 if prev == 'as' and cur == 'expected' else -1.9
        if cur in {'possible', 'applicable', 'available', 'appropriate'}:
            if prev == 'as' and cur != 'appropriate':
                return 0.0
            return -1.2
