        return 3.6 if modifier == 'that' else 2.9
    if modifier in VARIETY:
        return 2.7 if weak else 3.2
    if modifier in {'a', 'an'}:
        return 1.2 if weak else 1.5
    if modifier in COUNTS or modifier.isdigit():
