        return 1.65 * scale
    if word.lower() in SQL_COMMANDS:
        return 1.5 * scale
    if word in DECLARATIONS:
        return 0.75 * scale
    if word in CONTEXT_KEYWORDS:
        return 1.6 if scale == 1.0 else 0.0
    if word == 'test':
        return 1.92 * scale
    if word == 'Le':
        return 1.60 * scale
