        return -0.25
    if THAI.search(s):
        return 0.4
    if s.startswith(' '):
        return -0.08
    return 0.1 if word.isascii() and word.istitle() else 0.0



NECESSITY = {'need', 'require', 'necessary', 'obligation', 'must', 'essential'}
ABILITY = {
    'can', 'cannot', 'able', 'unable', 'capable', 'ability',
    'enable', 'allow', 'possible', 'impossible',
}


@lru_cache(maxsize=32768)
def lexical_value(token):
    word = token.strip().lower()
    value = -0.0025
    if word.isascii() and word.isalpha():
        bases = set(wordnet.base_forms(word)) | {word}
        if bases & ABILITY:
            value -= 0.04
        if bases & NECESSITY:
            value -= 0.035
