    if token.startswith("<|"):
        return 0.13
    if token == "" or "�" in token:
        return -0.2
    if token in CODE_WORDS:
        return 0.8
    if token[0] == " ":
        return -0.15
    if token[0] in OPENERS:
        return 0.5
    if token[0].isdigit():
        return 0.3 if token in ("0", "2") else -0.4
    if token[0] in BREAKS:
