from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def familiarity(word):
    return zipf_frequency(word.lower(), 'en')


def continuation(word, previous, token, pieces, spaced, line_start):
    frequency = familiarity(word + token)
    if frequency > 3.3:
        if line_start:
            if token[:1].isupper():
                return -0.24
            return -0.93 if familiarity(word) > 3.55 else -0.55
        if not spaced:
            return -0.62 if previous[:1].isupper() else -0.23
        return -0.11 if not token[:1].isupper() else 0.03
    if previous[:1].isupper():
        if len(word) == 1:
            return -0.88 if frequency > 2.15 else -0.40
        return -0.23 if pieces == 1 else -0.01
    if not spaced:
        return -0.19 if frequency > 0 else -0.03
    return -0.005


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, False, False)
    _, previous, word, pieces, spaced, line_start = carry
    token = prefix.token_strings[-1]
    value = -0.004
    if token[:1].isalpha() and previous[-1:].isalpha():
        value = continuation(word, previous, token, pieces, spaced, line_start)

    # Keep only the alphabetic run at the end of the current token.
    tail = ''
    for char in reversed(token):
        if not char.isalpha():
            break
        tail = char + tail
    if tail:
        if len(tail) == len(token) and word:
            word += tail
            pieces += 1
        else:
            word, pieces = tail, 1
            spaced = token[:1].isspace()
            line_start = '\n' in previous or prefix.position == 0
    else:
        word, pieces = '', 0
    return (doc, token, word, pieces, spaced, line_start), value

