KEYWORDS = {"using", "import", "namespace", "as", "static"}


def current_line(strings):
    parts = []
    for s in reversed(strings):
        if "\n" in s or "<|endoftext|>" in s:
            parts.append(s.split("\n")[-1])
            break
        parts.append(s)
    return "".join(reversed(parts))


