READS = ()


def _fill(s):
    """What a run-token is made of: one repeated character, or spaces mixed with
    no-break spaces (indentation). None for any other token."""
    if len(s) < 2:
        return None
    if len(set(s)) == 1:
        return s[0]
    if set(s) <= {" ", "\xa0"}:
        return "indent"
    return None


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
