COORDINATORS = frozenset('and or but'.split())
CONNECTORS = frozenset('so then thus hence therefore'.split())
SUBORDINATORS = frozenset('that if whether because for though although'.split())
RELATIVES = frozenset('what which where when'.split())
PURPOSES = frozenset('goal aim purpose objective intention'.split())
ITALIAN = frozenset('il lo gli le la di del della che e è un una nel con'.split())


def response(token, previous, recent):
    word = token.strip()
    prev = previous.strip().lower()
    end = previous[-1:]
