        if word[0] in '\"“‘':
            return 1.5
        if word == 'To':
            if not previous:
                return -0.24
            if previous.rstrip().endswith(('-', '–', '—', '•', '*')):
                return 1.7
            if token == 'To' and not end.isspace() and end not in '\"(“':
                return 0.0  # embedded in an identifier
            if end.isspace() or end in '.!?:;\"(“':
                return 1.25
            return 0.5
