            return 0.14
        if token == 'to' and previous:
            if end in '\"“':
                return 1.2
            if end == '(':
                return 0.7
            return 0.05 if end.isspace() else 0.1
        if prev in COORDINATORS:
            return 1.85
        if prev in CONNECTORS:
            return 1.35
        if prev in SUBORDINATORS or prev in ('not', 'never'):
            return 1.05
        if prev in RELATIVES:
            return 0.75
        if prev in COPULAS:
            purpose = any(w.rstrip('s') in PURPOSES for w in recent[-12:])
            return 1.47 if purpose else 0.6
        if prev == 'as':
            return 0.7
        if prev == 'order':
            return 0.32  # 'in order to'
        if previous.rstrip().endswith((';', '–', '—')):
            return 1.3
        if previous.rstrip().endswith(','):
