    if end.lower() in ('t', 'т') and token.lower() in ('o', 'u', 'ow', 'о', 'у'):
        return 0.35
    if token in (' å', ' Å'):
        return 0.5 if word == 'å' else 0.3
    if word.lower() == 'pour':
        return 0.97
    if word == 'per':
        return min(1.0, 0.4 * sum(w in ITALIAN for w in recent))
    if word == 'para':
        return 0.28
    if token == ' for':
        return 0.035
    if token == ' For':
        return -0.14
    if token == '4':
        if end.isalpha():
            return 0.3
        if end.isdigit():
            return -0.07
    return -0.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
