"""layers.1.mlp.down_proj:98 -- a weak, mostly-silent MLP feature.

Two parts, both small:

1. Document start. The component fires strongly (about -1 to +1.5) on the first token of a
   document, which the model sees with no context, so its size depends only on that token.
   Readable word classes give the sign: positive for a space-led lowercase word (" the",
   " of", " is"), a digit, or a hash mark; negative for a single capital letter or an
   opening bracket, dash or tab. Other first tokens get 0.

2. Everywhere else it is near zero (typically ±0.04). Line breaks give a small positive
   value and a few common prepositions (" in", " at", " to", " with", ...) a small negative
   value. These are the only token-level tendencies that were consistent across the data.

Explains very little variance (about 1-2%): the rest of the activation is diffuse
context-dependent noise that no short rule captures.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

DIGITS = set("0123456789")
OPENERS = set("([{-*@\t•")
LINE_BREAKS = {"\n", ".\n", "\n\n", ".\n\n"}
PREPOSITIONS = {" in", " at", " to", " with", " as", " on", " by", " be", " from", " an"}


def first_token_value(text: str) -> float:
    core = text.lstrip(" ")
    if not core:
        return 0.0
    if core in ("#", "##") or core[0] in DIGITS:
        return 0.3
    if text[0] == " " and core.isalpha() and core.islower():
        return 0.3
    if len(core) == 1 and core.isupper():
        return -0.3
    if core[0] in OPENERS:
        return -0.3
    return 0.0


def token_value(text: str) -> float:
    if text in LINE_BREAKS:
        return 0.015
    if text in PREPOSITIONS:
        return -0.012
    return 0.0


def step(carry, prefix, upstream: Mapping):
    text = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        return carry, float(first_token_value(text))
    return carry, float(token_value(text))

