    letter = len(text) == 1 and text.isascii() and text.isalpha()
    han = text in HAN or (text.startswith('第') and text[1:2] in HAN)
    kind = ('ordinal' if lower in ORDINALS else 'han' if han else
            'roman' if lower in ROMAN else 'letter' if letter else '')

    # Finish the previous numeral when a separator arrives.
    continued = digit and c['run'] and not token[:1].isspace()
    if not continued and c['run']:
        n = int(c['run'][-8:])
        c['numbers'].append((n, c['role'], pos))
        c['numbers'] = c['numbers'][-32:]
        if token.lstrip().startswith(('.', ')', ']', '、', '．')):
