    -0.2,  # 0
    9.5,   # 1
    5.2,   # 2
    1.6,   # 3
    5.5,   # 4
    5.5,   # 5
    6.9,   # 6
    7.7,   # 7
    6.3,   # 8
    6.4,   # 9
