        if "\n" in prev:
            return None, 0.5
        return None, 1.0
    if end in ("(", "[", '"', "'", ":"):
        return None, 0.9
    if prev in AUX:
        return None, 0.8
    if prev in NEG:
        return None, -0.3
    if prev in ZERO:
        return None, 0.0
    return None, 0.2

