def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if len(tokens) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    before = tokens[-2].strip().lower()
    now = tokens[-1]
    if not (now[:1].isascii() and now[:1].isalpha()):
        return None, 0.0
    if before.endswith("p") and now.startswith("h"):
        return None, -4.5
    if "ph" in before and len(before) <= 3:
        return None, -1.8
    return None, 0.0

programs.sol:
"""Recognize selected local format completions, not a single semantic topic.

Training examples have large spikes at document-initial `Title:`, sampling
`without replacement from`, and recognizable media/service URL prefixes.
Smaller rules cover Git, byte types/counts, LaTeX, and source/mail headers.
The rules give fixed approximate amplitudes; unrecognized cases give zero.
Keep only 256 trailing characters, resetting at document boundaries.
"""
import re

READS = ()
LANGUAGES = {'python', 'javascript', 'typescript', 'ts', 'java', 'cpp', 'c'}
SUFFIXES = {'.com', '.org', '.net', '.io', '.co', '.be'}
# Recognizable prefixes of video, image, social-media and code-paste URLs.
URL_PREFIXES = (
    ('youtube.com/channel', 10.7),
    ('/watch?v', 20.0),
    ('youtu.be', 17.0),
    ('/video?v', 8.7),
    ('desmos.com/calculator', 15.0),
    ('.bp.blogspot.com/-', 14.0),
    ('://pastebin.com', 14.0),
    ('.gstatic.com', 4.5),
    ('images.unsplash.com', 4.5),
    ('.imgur.com', 16.5),
    ('.twitter.com', 12.9),
    ('://t.co', 9.5),
    ('user-images.githubusercontent', 7.5),
    ('pic.twitter', 9.3),
    ('://i.imgur', 4.5),
    ('.bp.blogspot', 11.0),
    ('://miro.medium', 7.0),
    ('miro.medium.com/max', 6.5),
)


def activation(token, before):
    if token == ':' and before == 'Title':
        return 30.08
    if token == ' from' and before.endswith('without replacement'):
        value = 5.0 if before.strip() == 'without replacement' else 17.3
        return value

    completed = before + token
    for marker, value in URL_PREFIXES:
        if completed.endswith(marker):
            return value
    if token == '/status' and re.search(r'twitter\.com/[^/\s]+$', before):
        return 6.3
    if token in SUFFIXES:
        # Coarse default for a dotted, hostname-like suffix.
        host = re.split(r'[\s/"\'<>()[\]{}]', before)[-1]
        if re.search(r'\w', host):
            value = 0.5 if token != '.co' else 2.1
            ordinary_web = host.startswith('www.') or host.endswith('example')
            if token == '.com' and ordinary_web:
                value = 1.3
            return value
    if token == 'www' and before.endswith('://'):
        return -0.9

    # Git patches and filesystem conventions.
    if token == 'ignore' and before.endswith('.git'):
        return 1.6
    if token == 'tmp' and before.endswith('/'):
        return 2.0
    if token == 'index' and before.endswith('\n') and 'diff --git ' in before:
        return 3.6
    if token == ' a' and before.endswith('---'):
        return -1.15
    if token == ' a' and before.endswith('diff --git'):
        return -0.6
    if token == ' b' and before.endswith('+++'):
        return -3.8
    if token == '+++' and before.endswith('\n'):
        return -2.0
    if token == 'git' and before.endswith('diff --'):
        return -1.0

    # Code types, byte counts, mathematical markup, and code fences.
    if token == 'byte' and before.endswith('[]'):
        return 3.25
    if token == ' bytes' and re.search(r'\d+$', before):
        heading = before.rsplit('#', 1)[-1]
        golf = '#' in before and re.fullmatch(
            r'[^\n]{1,60},\s*\d+', heading.strip()
        )
        return 7.0 if golf else 1.5
    if token == ' serialVersionUID' and before.endswith(' long'):
        return 2.7
    if token == '}{' and before.endswith('array'):
        return 5.6
    if token == '}{' and before.endswith('tabular'):
        return 8.0
    if token in LANGUAGES and before.endswith('```'):
        return -1.1
    if token == '#define' and re.search(r'#ifndef[^\n]*\n$', before):
        guard = before.rsplit('#ifndef', 1)[-1].strip()
        header = re.search(r'_H(?:_|PP|$)', guard)
        return -7.0 if header else -2.5

    # Attribution and identifier punctuation in source headers and email.
    dated_header = re.search(
        r'(Created|Updated):[^\n]*\d{2}:\d{2}:\d{2}$', before
    ) if token == ' by' else False
    if dated_header:
        return 7.3
    if token == ' message' and before.endswith('wrote in'):
        return 10.5
    if token == ' <':
        if before.endswith('References:'):
            return 9.0
        if before.endswith('Message-ID:'):
            return 5.2
        if before.endswith(' in') and ('File ' in before or '.py:' in before):
            return 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = activation(token, before)
    tail = (before + token)[-256:]
    if '<|endoftext|>' in token:
        tail = ''
    return (doc, tail), value

programs.haiku:
"""layers.1.mlp.down_proj:123 as a set of readable text rules.

This component is polysemantic: it is nearly silent on ordinary text (about 0.05% of
tokens fire), and when it does fire it is on a few recognisable spots in web links, git
diffs, code and LaTeX. The program predicts its activation from the current token and the
few tokens before it, with no state carried between positions:

1. A document-opening header "Title:" right after <|endoftext|> gives a very large value.
2. Short-link and media hosts (pic.twitter.com, youtu.be, pastebin.com, youtube.com/watch
   ?v=) fire on the domain piece and on the query key, where an opaque ID comes next.
   Unsplash image links give a moderate value.
3. Other URL query keys (&w=, &ixid=, &fit=) and ordinary domain endings (.com, .org) in
   a link give small values.
4. Git diff headers: the "index" line after "diff --git" is positive; the "b" and "a"
   path markers on "+++" and "---" lines are negative.
5. Code and text idioms: Go "[]byte", "/tmp" paths, ".gitignore", a Usenet "wrote in
   message", a Message-ID "<", and LaTeX "\\begin{array}{".

Everything else predicts 0.
"""

READS = ()

# Hosts whose links end in an opaque ID (short links, media pages, paste sites).
LINK_HOSTS = ("pic.twitter", "youtu", "pastebin", "youtube", "imgur")
LINK_TOKENS = {".com", ".be", ".co", ".org", ".net", ".twitter", "?v"}
QUERY_KEYS = {"&w", "&ixid", "&fit", "?id"}


def before_on_line(prefix):
    """Text on the current line before the current token."""
    out = []
    for s in reversed(prefix.token_strings[:-1]):
        if "\n" in s:
            break
        out.append(s)
    return "".join(reversed(out))


def before_in_chunk(prefix):
    """Text since the last whitespace, before the current token (the current 'word' or URL)."""
    out = []
    for s in reversed(prefix.token_strings[:-1]):
        if s.strip() == "":
            break
        out.append(s)
    return "".join(reversed(out))


def recent(prefix, n=40):
    """The last n tokens' text, before the current token."""
    return "".join(prefix.token_strings[-n:-1])


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2].strip() if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    chunk = before_in_chunk(prefix)
    line = before_on_line(prefix)
    value = 0.0
    if prev2 == "<|endoftext|>" and prev == "Title" and tok == ":":
        value = 30.0  # document-opening "Title:" header
    elif tok in LINK_TOKENS and any(h in chunk for h in LINK_HOSTS):
        value = 10.0  # domain of a media/short link: an opaque ID follows
    elif tok in LINK_TOKENS and "unsplash" in chunk:
        value = 4.0
    elif (tok in QUERY_KEYS or tok == "?v") and "http" in chunk:
        value = 3.0
    elif tok in {".com", ".org", ".co", ".net", ".be"} and "http" in chunk:
        value = 0.5
    elif tok == "index" and line == "" and "diff --git" in recent(prefix):
        value = 3.8  # git diff blob line
    elif line.startswith("+++") and tok.strip() == "b":
        value = -4.0  # git diff new-file path marker
    elif line.startswith("---") and tok.strip() == "a":
        value = -1.5  # git diff old-file path marker
    elif tok.strip() == "byte" and prev == "[]":
        value = 3.5  # Go []byte
    elif tok == " message" and "wrote in" in recent(prefix, 6):
        value = 10.0  # Usenet reply header
    elif tok == " <" and "Message-ID:" in line:
        value = 5.0
    elif tok == "tmp" and prev == "/":
        value = 2.0  # /tmp paths
    elif tok == "ignore" and prev == ".git":
        value = 1.5  # .gitignore
    elif tok == "}{" and prev == "array":
        value = 5.5  # LaTeX \begin{array}{
    return carry, value

programs.sol:
"""An initial-token pulse, lasting through repetitions of that token.

Its strength depends coarsely on the token's writing system, case and
spacing. Once a different token appears, the pulse ends for this document.
A few grammatical and code-opening word classes refine its strength.
These classes approximate token-specific variation, not semantic context.
"""
import unicodedata

READS = ()

AUXILIARIES = frozenset("""
    am is are was were be been being have has had do does did
    can could will would shall should may might must
""".split())
CODE_DECLARATIONS = frozenset("""
    class def import from package using public private protected
    static void int #include
""".split())


def initial_strength(text):
    word = text.strip()
    if text.startswith('<|'):
        return 2.9
    if not word:
        if text == '\r':
            return -2.0
        if '\t' in text:
            return 12.0 if text == '\t' else 8.4
        if '\n' in text:
            return 8.2 if text.startswith('\n') else 4.2
        return 3.5 if len(text) == 1 else 8.0
    if '\ufffd' in text:
        return 3.7
    if word.isdecimal():
        return 5.7
    if any(any(script in unicodedata.name(c, '')
               for script in ('CJK', 'HIRAGANA', 'KATAKANA'))
           for c in word):
        return 4.3
    if not any(c.isalpha() for c in word):
        return 4.2 if text[0].isspace() else 6.5
    if text in CODE_DECLARATIONS:
        return 13.3
    if word.lower() in AUXILIARIES:
        return 9.4
    if text[0].isspace():
        return 5.7
    return 8.3 if word[0].isupper() else 7.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, initial_strength(prefix.token_strings[-1]), True)
    doc, initial, strength, active = carry
    active = active and token == initial
    return (doc, initial, strength, active), strength if active else 0.001

"""Approximate sentence endings and a few languages' locative prepositions.

Question/exclamation endings are negative. Explicit question cues soften
this: English question openers, Spanish's inverted question mark, and
Chinese final question particles. Period-plus-newline endings are positive,
especially after imperative requests. Recent word frequencies distinguish
several languages' words for 'in' from look-alike fragments. Other cases
receive a small negative background, with exceptions for a title field and
Rust punctuation. The short text history resets at document boundaries.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

QUESTION = re.compile(
    r'^[\W\d_]*(what|why|who|whom|whose|which|where|when|how|'
    r'can|could|would|will|shall|should|is|are|was|were|do|does|did|'
    r'have|has|had|may|might)\b', re.I)
COMMAND = re.compile(
    r'^[\W\d_]*(find|determine|compute|write|list|calculate|use|give|'
    r'express|identify|estimate|evaluate|show|prove|solve|simplify|'
    r'convert|select|choose|complete|explain|describe|tell)\b', re.I)


@lru_cache(maxsize=10000)
def word_frequency(word, lang):
    return min(6.0, zipf_frequency(word.lower(), lang))


def language(history, candidates):
    words = re.findall(r'[^\W\d_]{2,}', history[-250:])[-24:]
    return max(candidates, key=lambda lang: sum(
        word_frequency(word, lang) for word in words))


def predict(token, history):
    bare = token.strip()
    word = bare.lower()
    boundary = token.startswith(' ') or not history or history[-1].isspace()
    if boundary:
        # Spanish, Portuguese and Slavic locative prepositions.
        if word == 'en':
            lang = language(history, ('nl', 'es', 'fr'))
            return {'es': 0.72, 'fr': -0.10, 'nl': -0.01}[lang]
        if word == 'em':
            return 0.66 if language(history, ('en', 'pt')) == 'pt' else 0.01
        if word == 'v':
            return 0.48 if language(history, ('en', 'cs', 'sk')) != 'en' else 0.03
        if word == 'w':
            return 0.84 if language(history, ('en', 'pl')) == 'pl' else 0.02
        if word == 'в':
            return 0.55 if bare.isupper() else 0.47

    if token == '\n\n':
        return -0.05
    newline = '\n' in token
    punctuation = bare and not any(c.isalnum() for c in bare)
    if not punctuation:
        return -0.003
    sentence = re.split(r'[.!?。！？\n]', history)[-1]
    direct = bool(QUESTION.match(sentence)) or '¿' in sentence
    command = bool(COMMAND.match(sentence))
    if ('?' in bare or '？' in bare):
        # Rust's debug-format marker, e.g. {:?}, is not a question.
        if re.search(r'\{:[^{}\n]*$', history[-60:]):
            return -0.50
        if history.rstrip().endswith(tuple('吗嗎呢么麼')):
            return -0.02 if newline else -0.35
        if '？' in bare:
            return -0.16 if newline else -0.52
        if newline:
            if direct:
                return 0.08
            return -0.30 if token.count('\n') == 1 else -0.52
        return -0.20 if direct else (-0.91 if bare == '?' else -0.82)
    if ('!' in bare or '！' in bare):
        if '=' in bare or '(' in bare or re.search(
                r'(?:[=({,\[\\]|\b(?:assert(?:_eq|_ne)?|return|'
                r'e?print(?:ln)?|format|panic|vec|write(?:ln)?))\s*$', history):
            return 0.0
        if newline:
            return -0.24
        if bare == '！':
            return -0.36
        return -0.16 if token.startswith(' ') else -0.45
    if newline and ('.' in bare or '。' in bare):
        if bare.count('.') > 1:
            return -0.02
        if '"' in bare or '”' in bare:
            return 0.04
        if command:
            return 0.43
        return 0.13 if token.count('\n') == 1 else 0.09
    if token == '.' and command:
        return 0.31
    if token == ':' and history.strip() == 'Title':
        return -4.21  # A document's title-field delimiter, not prose punctuation.
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    past = carry[1] if carry is not None and carry[0] == doc else b''
    history = past.decode('utf-8', errors='ignore')[-600:]
    token = prefix.token_strings[-1]
    value = predict(token, history)
    past = (past + prefix.token_bytes[-1])[-2400:]
    return (doc, past), float(value)

programs.haiku:
"""Question and exclamation marks push this component negative. Carriage returns, the
word "in" in several other languages, and a sentence end just before a line break push
it positive. Everything else is about zero.

The activation is read from the current token's own text; no earlier tokens are needed:
- a question mark ("?" or the full-width "？") is strongly negative, about -0.7;
  when it is followed by a line break or a quote ("?\n", "?\n\n", "?\""), it is weaker,
  about -0.3;
- an exclamation mark ("!" or "！") is moderately negative, about -0.4; the code operator
  "!=" is not one;
- a carriage return "\r" is strongly positive, about +0.8 (it sits mostly in long runs
  of terminal-style "\r" text, so its size varies a lot);
- "in" in another language (Russian "в", Spanish/Portuguese "en"/"em", Polish "w")
  is positive, about +0.4;
- a period or Chinese full stop that ends a line ("." then a newline) is weakly
  positive, about +0.12.
"""

from collections.abc import Mapping

READS = ()

IN_OTHER_LANGUAGES = {" в", " В", "В", " en", " em", " w"}
SENTENCE_END_BEFORE_NEWLINE = {".\n", ".\n\n", "。\n"}


def guess(token: str) -> float:
    """The activation this token's own text predicts."""
    if "?" in token or "？" in token:
        return -0.3 if ("\n" in token or '"' in token or "”" in token) else -0.7
    if ("!" in token and "!=" not in token) or "！" in token:
        return -0.4
    if token == "\r":
        return 0.8
    if token in IN_OTHER_LANGUAGES:
        return 0.4
    if token in SENTENCE_END_BEFORE_NEWLINE:
        return 0.12
    return 0.0


def step(carry, prefix, upstream: Mapping):
    """Predict this position's activation from its own token; no state is needed."""
    return carry, guess(prefix.token_strings[-1])

programs.sol:
"""A sparse lexical response to cross-like words and spellings.

The main positives are English cross, translations such as cruz/croix/Kreuz,
and Chinese 穿 (pierce/pass through/wear). Split spellings can be stronger
than whole tokens. Smaller rules cover cr-/clo- fragments, 叉, 过/過,
'close to', and paired middle dots; c_str, EC2 and hex C2 are negative.
This is not a general crossing-meaning detector. Unmatched text gets zero.
Only the current token and a short, document-local spelling tail are used.
"""
import re

READS = ()
PIERCE_BYTES = '穿'.encode('utf-8')


def response(token, previous, tail):
    word = token.strip()
    low = word.lower()
    if re.fullmatch(r'cross(?:ed|es|ings?)?', low):
        if low.startswith('crossing'):
            return 3.3
        if low == 'crossed':
            return 4.3
        if word == 'Cross' and previous.strip() in {'Red', 'Holy', 'Iron'}:
            return 7.7
        if not token[0].isspace() and tail.lower().endswith('criss'):
            return 7.8
        return 5.2 if word[0].isupper() else 4.6
    if low.lstrip('._-') == 'cross':
        return 7.7 if low.startswith('-') else 4.6
    if low in {'crossover', 'crossword'}:
        return 1.7
    if low == 'cruz':
        return 4.8
    if low in {'cro', 'cru', 'cruc', 'crochet'}:
        return 2.5 if low == 'cro' else 1.4 if low == 'cru' else 1.9
    if token == '穿':
        return 5.8
    if token in {'穿着', '穿越', '穿过', '穿上'}:
        return 2.4
    if token in {'过', '過'}:
        return 0.6
    if token == '叉':
        return 6.1 if previous == '前' else 1.4
    if low == 'to' and previous.strip().lower() == 'close':
        return 2.4
    if low == 'close':
        return 0.24
    if token == '··':
        return 2.2

    # Spelling continued across a token boundary, not across whitespace.
    if not token or token[0].isspace() or not tail:
        return 0.0
    before, now = tail.lower(), token.lower()
    if now == '_str' and before.endswith('c'):
        return -7.7
    if now == '2':
        if before in {'ec', 'mockec'}:
            return -4.9
        if before.endswith('xc'):
            return -0.6
    if not token[0].isalpha():
        return 0.0
    joined = before + now
    if ('cross' in joined or 'kross' in joined) and not any(
        root in before for root in ('cros', 'kros')
    ):
        return 1.1 if 'across' in joined else 8.5
    if (joined.startswith(('cros', 'kros'))
            and not before.startswith(('cros', 'kros'))):
        return 8.5
    # Spanish, French, German and Russian cross spellings.
    translations = (
        ('cruz', 10.9), ('croix', 9.6), ('kreuz', 8.8), ('кросс', 10.1),
    )
    for root, value in translations:
        if root in joined and root not in before:
            return 2.5 if root == 'cruz' and not joined.endswith(root) else value
    if before.endswith('cross') and now in {'ed', 'ing'}:
        return 6.5
    if 'クロス' in joined and 'クロス' not in before:
        return 12.0
    if before.endswith('크') and now == '로':
        return 5.0
    if before.endswith('크로') and now == '스':
        return 8.5
    if before.endswith('к') and now.startswith('рест'):
        return 4.0
    if before in {'cr', 'kr'} and now.startswith(('uc', 'ux', 'iss')):
        return 5.8
    if before in {'cro', 'kro'}:
        return 2.4
    if before in {'cr', 'kr'}:
        return 0.8
    if before.endswith('c'):
        if now.startswith('lock'):
            return 3.0
        if now.startswith('lose') and before == 'c':
            return 4.5
        if now == 'lo':
            return 2.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, byte_tail = '', '', b''
    else:
        previous, tail, byte_tail = carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    byte_tail = (byte_tail + prefix.token_bytes[-1])[-8:]
    if '\ufffd' in token:
        if byte_tail.endswith(PIERCE_BYTES):
            value = 10.5
        elif byte_tail.endswith(PIERCE_BYTES[:2]):
            # This UTF-8 prefix is shared with other Han characters.
            value = 0.8
    match = re.search(r'\w+$', tail + token)
    tail = match.group()[-24:] if match else ''
    return (doc, token, tail, byte_tail), value

"""Approximate short-range conditional, obligation, and request constructions.

The largest negative responses are reader-directed hypotheticals ("if you
need/want...") and infinitives such as "have to" and "if ... were to".
Chinese conditionals behave similarly. Giving/request words in Chinese,
some web-interface labels, and import/header syntax have positive responses.
The constants are approximate amplitudes, not a complete account of the
component: weak lexical variation and unusual boilerplate are left out.
"""
import re
from functools import lru_cache
import cedict

READS = ()

# baseline; additional response to a conditional within 8, 20, or 45
# characters; additional response to a nearby relative-clause introducer.
GRAMMAR = {
    'need': (-.08, -2.8, -.3, -.4, -.12),
    'needs': (-.05, -.3, -.1, 0., -.03),
    'needed': (-.08, -.9, 0., 0., -.12),
    'want': (-.12, -1.2, -.6, -.06, 0.),
    'must': (0., -.2, -.9, -.05, -.28),
    'can': (-.01, -.25, -.04, -.04, -.06),
    'could': (-.05, -.15, -.03, -.06, -.05),
    'will': (.05, -1.2, -.2, 0., -.15),
    'would': (-.03, -.1, -.02, -.02, -.06),
    'may': (0., -.8, .2, 0., .07),
    'might': (-.06, 0., 0., 0., -.06),
    'necessary': (.01, -.7, .1, 0., .03),
    'to': (0., -.45, -.28, 0., -.07),
    'be': (.04, 0., .03, .03, .02),
    'please': (-.04, 0., 0., -.03, 0.),
}
ALIASES = {'wants': 'want', 'wanted': 'want', 'needing': 'need',
           'required': 'necessary', "'ll": 'will', '’ll': 'will'}
CONDITIONAL = re.compile(r'\b(if|unless|whether)\b', re.I)
RELATIVE = re.compile(r'\b(who|which|that|when|where|since|before)\b', re.I)
CHINESE_IF = re.compile('如果|假如|若|如|倘')
TRANSFER = re.compile(
    r'\b(give|hand|pass|send|deliver|transfer|share|assign|return|entrust|'
    r'present|offer|sell|lend|donate|feed|allocate|distribute|transmit|'
    r'provide|spread)\b', re.I)


@lru_cache(maxsize=4096)
def transfer_verb(text):
    """Does the preceding Chinese word mean giving or moving something?"""
    return any(TRANSFER.search(gloss)
               for n in range(1, min(4, len(text)) + 1)
               for gloss in cedict.glosses(text[-n:]))


def predict(token, before):
    word = token.strip().lower()
    group = ALIASES.get(word, word)
    value = 0.
    if group in GRAMMAR or word == 'for':
        matches = list(CONDITIONAL.finditer(before))
        tail = before[matches[-1].end():] if matches else ''
        distance = len(tail) if matches else 999
        relatives = list(RELATIVE.finditer(before))
        relative = bool(relatives and len(before)-relatives[-1].end() <= 12)
        if group in GRAMMAR:
            base, near, middle, far, rel = GRAMMAR[group]
            value = base + (near if distance <= 8 else
                            middle if distance <= 20 else
                            far if distance <= 45 else 0.)
            value += rel * relative
        # The addressee matters: these are particularly strong in instructions.
        if distance <= 8:
            subject = tail.strip().lower()
            if group == 'need':
                value = -3.35 if subject == 'you' else -2.1 if subject == 'we' else -1.3
            elif group == 'want':
                value = -1.4 if subject in ('you', 'we') else -.4
            elif group in ('can', 'could'):
                value = -.75 if subject == 'you' else -.1
            elif group == 'will':
                value = -4.8 if subject == 'you' else -1.15
        words = re.findall('[a-z]+', before.lower())
        last = words[-1] if words else ''
        if group == 'to':
            if last in ('have', 'has', 'had', 'having'):
                value -= .38 + (2.1 if distance <= 25 else 0.)
                if distance <= 25 and last == 'had': value -= 1.5
            elif last in ('want', 'wants', 'wanted'):
                value -= .19 + (1.4 if distance <= 25 else 0.)
            elif last in ('need', 'needs', 'needed', 'necessary', 'required'):
                value -= 1.5 if distance <= 25 else 0.
            elif last in ('were', 'was', 'is', 'are', 'am', 'be'):
                if distance <= 25: value -= 1.5
            elif last in ('going', 'about'):
                value += .06 - (1.4 if distance <= 35 else 0.)
            elif last in ('try', 'tries', 'tried', 'trying', 'attempt', 'attempting'):
                value -= .07 + (.15 if distance <= 35 else 0.)
            elif last == 'like' and 'would' in before[-20:].lower():
                value -= .3
        elif group == 'be' and last in ('must', 'should'):
            value += .2
        elif group == 'please' and distance <= 100:
            value += .55
        elif word == 'for' and last == 'looking' and distance <= 35:
            value -= 1.
    elif word in ('需要', '需', '要', '想要'):
        matches = list(CHINESE_IF.finditer(before[-25:]))
        distance = len(before[-25:])-matches[-1].end() if matches else 999
        if distance <= 3: value = -2. if word == '想要' else -4.5
        elif distance <= 10: value = -.6
    elif word.startswith(('给', '給')) and len(word) <= 3:
        value = .75 + 1.2 * transfer_verb(before)
        value += 1.7 * bool(re.search('把|将|將|被', before[-35:]))
        value -= 1.1 * bool(re.search('要|不能|无法|無法', before[-4:]))
        value -= 3. * bool(CHINESE_IF.search(before[-12:]))
    elif word in ('请', '請', '，请', '，請', '请联系', '請聯繫'):
        value = .65 + (1. if len(word) >= 3 else 0.)
        request_cue = '如|若|问题|問題|更多|详情|詳情|详细|詳細|非经|非經'
        if re.search(request_cue, before[-30:]):
            value += 1.3
    elif word in ('联系', '聯繫', '告诉', '告訴'):
        value = .6
    elif word == 'android' and before.endswith('import'):
        value = 5. if before.endswith('\n\nimport') else 3.4
    elif word == 'future' and before.endswith('from __'):
        value = 3.5
    elif token == ':' and (before == 'Title' or before.endswith('<|endoftext|>Title')):
        value = 4.6
    elif token and set(token) == {'·'}:
        value = .65
    elif word == 'question' and before.lower().endswith('rate this'):
        value = 3.5
    elif word == 'reply' and before.lower().endswith('leave a'):
        value = 4.
    elif word == 'sites' and before.lower().endswith('share on other'):
        value = 2.6
    elif word == 'on' and before.lower().endswith('share'):
        value = 2.2
    elif word == 'posts' and re.search('(similar|display|recommended)$', before, re.I):
        value = 3.
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (document, (before + token)[-100:]), float(value)
